jsonTools.init:
function init(eli) {
  eli = eli || window.eli;
  if (!eli || !eli.register) return;

  // 2026-06-09: opened to all users (was andrew-only alpha). The strip
  // is OFF by default — users opt in via the 🧩 manager (tile or
  // Settings → Interface → Dashboard Widgets).

  // ── Kill switch ───────────────────────────────────────────────────
  try {
    eli.settings.register("dashboard_widgets_enabled", {
      default: true, type: "boolean", adminPushable: true,
      describe: "Dashboard widgets strip enabled",
    });
  } catch (_) {}
  function _featureOn() {
    try { return eli.settings.get("dashboard_widgets_enabled") !== false; }
    catch (_) { return true; }
  }

  // ── Layout persistence — config store, canonical {key, value} shape ─
  var LAYOUT_KEY = "widget_layout";
  var _layout = null; // { master, enabled:{}, order:[], sizes:{} }
  // Hard cap — exactly two widget boxes side by side, so the
  // dashboard's vertical height never changes with widget count.
  var MAX_ACTIVE = 2;
  function _defaultLayout() {
    return {
      // master:false — widgets are opt-in (off for new users). 2026-06-13:
      // no widget is pre-checked either; checking one in the manager
      // auto-enables the master toggle (see tgl.onchange below).
      master: false,
      enabled: { word_day: false, trivia_day: false, joke_day: false, case_day: false, patent_day: false, tip_day: false, playbook_day: false, trophies_next: false },
      order: ["trophies_next", "word_day", "trivia_day", "joke_day", "case_day", "patent_day", "tip_day", "playbook_day"],
      sizes: {},
      variants: {},   // per-widget content variant (e.g. contract|patent)
    };
  }
  function _activeCount() {
    if (!_layout) return 0;
    var n = 0;
    _layout.order.forEach(function (id) {
      if (_layout.enabled[id] && _findWidget(id)) n++;
    });
    return n;
  }
  function _loadLayout() {
    return eli.storage.get("config", LAYOUT_KEY).then(function (row) {
      var v = (row && row.value) || {};
      var d = _defaultLayout();
      _layout = {
        master:   v.master === undefined ? d.master : !!v.master,
        enabled:  v.enabled || d.enabled,
        order:    Array.isArray(v.order) && v.order.length ? v.order : d.order,
        sizes:    v.sizes || {},
        variants: v.variants || {},
      };
      // Widgets shipped after the user's layout was first saved would
      // otherwise never appear in the manager — append missing ids.
      d.order.forEach(function (id) {
        if (_layout.order.indexOf(id) === -1) _layout.order.push(id);
      });
      return _layout;
    }).catch(function () { _layout = _defaultLayout(); return _layout; });
  }
  function _saveLayout() {
    return eli.storage.put("config", { key: LAYOUT_KEY, value: _layout, updatedAt: Date.now() })
      .catch(function () {});
  }

  // ── Deterministic daily index — same item all day, rotates at local
  //    midnight. Whole team would see the same item (shared watercooler).
  function _curDoy() {
    var now = new Date();
    var start = new Date(now.getFullYear(), 0, 0);
    return Math.floor((now - start) / 86400000);
  }
  function _dayIndex(len, salt) {
    if (!len) return 0;
    return (_curDoy() + (salt || 0)) % len;
  }
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  // ── Content: Word of the Day ──────────────────────────────────────
  var WORDS = [
    { t: "Force Majeure", d: "Excuses performance when extraordinary events beyond the parties' control intervene.", w: "List the triggering events — courts read these clauses narrowly." },
    { t: "Indemnification", d: "One party's promise to cover another's losses from specified claims.", w: "Watch the trio: scope, cap, and defense obligation — each is negotiated separately." },
    { t: "Novation", d: "Replacing a party (or obligation) with a new one, extinguishing the original.", w: "Unlike assignment, novation needs everyone's consent — including the party staying put." },
    { t: "Estoppel", d: "Bars a party from contradicting what it previously asserted when others relied on it.", w: "Your emails during a deal can estop your litigation position later." },
    { t: "Contra Proferentem", d: "Ambiguity is construed against the party that drafted it.", w: "The hidden tax on sloppy drafting — and a reason templates get audited." },
    { t: "Quantum Meruit", d: "Recovery of the reasonable value of services when no enforceable contract covers them.", w: "It's the fallback when work started before the contract was signed." },
    { t: "Severability", d: "If one clause fails, the rest of the agreement survives.", w: "Without it, one unenforceable term can take the whole contract down." },
    { t: "Consideration", d: "The bargained-for exchange that makes a promise enforceable.", w: "Recitals of $1 usually work — past consideration usually doesn't." },
    { t: "Peppercorn", d: "Nominal consideration — trivially small but legally sufficient.", w: "Courts ask whether consideration exists, not whether the deal was wise." },
    { t: "Condition Precedent", d: "An event that must occur before a duty to perform arises.", w: "Spot the difference between a promise (breach = damages) and a condition (no duty at all)." },
    { t: "Liquidated Damages", d: "Pre-agreed damages for a specific breach.", w: "Enforceable as a reasonable estimate — struck down as a penalty if punitive." },
    { t: "Integration Clause", d: "Declares the written agreement the complete and final deal.", w: "It activates the parol evidence rule — side emails stop counting." },
    { t: "Tolling", d: "Pausing the running of a limitations period.", w: "Tolling agreements buy negotiation time without losing claims." },
    { t: "Waiver", d: "Intentional relinquishment of a known right.", w: "'No-waiver' clauses exist because accepting late payment twice can waive timeliness." },
    { t: "Material Breach", d: "A failure serious enough to excuse the other side's performance.", w: "Materiality decides whether you can walk away or only sue for damages." },
    { t: "Cure Period", d: "Time given to fix a breach before remedies kick in.", w: "Notice-and-cure turns 'gotcha' terminations into negotiations." },
    { t: "Covenant", d: "A promise to do (affirmative) or not do (negative) something.", w: "Non-competes are negative covenants — scope and duration drive enforceability." },
    { t: "Recitals", d: "The 'whereas' clauses describing background and intent.", w: "Usually not binding — but courts read them when operative terms are ambiguous." },
    { t: "Counterparts", d: "Permits signing in separate copies that together form one agreement.", w: "The clause that quietly blesses scattered e-signatures." },
    { t: "Ipso Facto", d: "'By the fact itself' — clauses triggered automatically by an event, like bankruptcy.", w: "Ipso facto termination-on-bankruptcy clauses are largely unenforceable in bankruptcy." },
    { t: "Pari Passu", d: "'On equal footing' — obligations rank equally without preference.", w: "A lender phrase that migrates into IP and payment waterfall clauses." },
    { t: "Time Is of the Essence", d: "Makes timely performance a material term.", w: "Without it, 'late' is usually a damages problem, not a termination right." },
    { t: "Assignment", d: "Transferring contract rights to a third party.", w: "Anti-assignment clauses often carve out affiliates and M&A — read the carve-outs first." },
    { t: "Representations & Warranties", d: "Statements of fact (reps) and promises they're true (warranties).", w: "Reps support fraud claims; warranties support breach claims — survival periods differ." },
    { t: "Survival Clause", d: "Lists the obligations that continue after the agreement ends.", w: "If confidentiality or indemnity isn't listed, expect an argument that it died with the contract." },
    { t: "Notices Clause", d: "Specifies how, where and to whom formal notices must be sent.", w: "Update addresses and add email carefully — a notice to the wrong place may not count." },
    { t: "Governing Law", d: "Chooses which jurisdiction's law interprets the contract.", w: "Add 'without regard to conflict-of-laws principles' or the chosen law may point elsewhere." },
    { t: "Forum Selection", d: "Designates the courts where disputes must be brought.", w: "Say 'exclusive' if you mean it — a merely permissive forum clause allows suits elsewhere." },
    { t: "Jury Waiver", d: "Parties give up the right to a jury trial for disputes under the contract.", w: "Make it conspicuous; some states, like California, refuse to enforce pre-dispute jury waivers." },
    { t: "Amendment Clause", d: "Requires changes to the agreement to be in a signed writing.", w: "Courts sometimes enforce oral changes anyway — conduct matters, so document every change." },
    { t: "Headings Clause", d: "States that section headings are for convenience and don't affect meaning.", w: "A mislabeled heading can still confuse a reader — keep headings accurate anyway." },
    { t: "Further Assurances", d: "Each party agrees to sign documents and take steps needed to carry out the deal.", w: "Handy for IP assignments — add 'at the requesting party's expense' to avoid cost fights." },
    { t: "Relationship of the Parties", d: "Confirms the parties are independent contractors, not partners or agents.", w: "Labels help, but conduct controls — control over the work can still create agency." },
    { t: "Third-Party Beneficiary", d: "A non-party entitled to enforce a contract made for its benefit.", w: "Add a 'no third-party beneficiaries' clause unless affiliates or indemnitees need rights." },
    { t: "Cumulative Remedies", d: "Remedies in the contract add to, rather than replace, remedies at law.", w: "Conflicts with 'sole and exclusive remedy' language — decide which one you mean." },
    { t: "Sole and Exclusive Remedy", d: "Limits a party to the remedy stated in the contract for a given breach.", w: "If the exclusive remedy fails its essential purpose, UCC 2-719 may revive other remedies." },
    { t: "Specific Performance", d: "A court order requiring a party to actually perform rather than pay damages.", w: "Courts grant it when money is inadequate — stipulating that helps but doesn't guarantee it." },
    { t: "Injunctive Relief", d: "A court order to do or stop doing something, often to prevent irreparable harm.", w: "NDAs usually add 'without posting bond' — courts may still require one." },
    { t: "Irreparable Harm", d: "Injury that money damages cannot adequately fix.", w: "A contractual stipulation of irreparable harm is persuasive, not binding, on a court." },
    { t: "Expectation Damages", d: "Money that puts the injured party where it would have been had the contract been performed.", w: "The default contract measure — lost profits often sit here, so check your exclusions." },
    { t: "Reliance Damages", d: "Recovery of costs spent relying on the contract before the breach.", w: "Useful when profits are too speculative to prove — keep records of sunk costs." },
    { t: "Restitution", d: "Returning a benefit conferred so the other side isn't unjustly enriched.", w: "Available even when the contract fails — the focus is the gain, not your loss." },
    { t: "Consequential Damages", d: "Indirect losses flowing from special circumstances, like lost profits or business.", w: "Excluding them can gut your own recovery — consider carve-outs for confidentiality and IP." },
    { t: "Incidental Damages", d: "Reasonable costs of dealing with a breach, like inspection, storage or cover.", w: "Often swept into exclusions with consequentials — decide if you really want that." },
    { t: "Direct Damages", d: "Losses that flow naturally and necessarily from the breach itself.", w: "The line between direct and consequential is fact-specific — define key items expressly." },
    { t: "Mitigation", d: "The injured party's duty to take reasonable steps to limit its losses.", w: "Damages avoidable through reasonable effort are not recoverable — act promptly." },
    { t: "Limitation of Liability", d: "Caps or excludes the damages a party can recover under the contract.", w: "Check carve-outs: indemnity, confidentiality, gross negligence and IP often sit outside the cap." },
    { t: "Hell or High Water", d: "Requires a party to keep paying regardless of disputes or performance problems.", w: "Common in leases and financings — it blocks set-off, so scrutinize it in supply deals." },
    { t: "Super Cap", d: "A higher separate liability cap for specific risks like data breaches.", w: "Clarify whether the super cap is in addition to or inclusive of the general cap." },
    { t: "Gross Negligence", d: "Conduct showing reckless disregard for the safety or rights of others.", w: "Definitions vary by state — commonly carved out of caps, so consider defining it." },
    { t: "Willful Misconduct", d: "Intentional wrongdoing done with knowledge that it is wrong.", w: "Often paired with gross negligence in carve-outs — both widen exposure beyond the cap." },
    { t: "Hold Harmless", d: "A promise not to hold the other party liable for certain losses.", w: "Some courts treat it as identical to indemnify — others read it as a release. Be explicit." },
    { t: "Duty to Defend", d: "An obligation to provide and pay for the defense of a claim.", w: "Broader than indemnity — it can arise on allegations alone, before liability is proven." },
    { t: "Indemnification Procedure", d: "Steps for notice, control of defense and settlement of indemnified claims.", w: "Bar the indemnitor from settling without consent if the settlement admits fault." },
    { t: "Release", d: "A party gives up claims against another, usually in exchange for consideration.", w: "California Civil Code 1542 requires an express waiver to release unknown claims." },
    { t: "Covenant Not to Sue", d: "A promise not to bring a claim, without extinguishing the claim itself.", w: "Common in IP settlements — check whether it binds successors and covers customers." },
    { t: "Accord and Satisfaction", d: "Settling a disputed debt by agreeing to and accepting a different performance.", w: "Cashing a 'paid in full' check can settle the dispute — read the memo line." },
    { t: "Anticipatory Repudiation", d: "A clear statement before performance is due that a party won't perform.", w: "You may treat it as breach now — but ambiguous grumbling isn't repudiation." },
    { t: "Adequate Assurance", d: "A demand for assurance of performance when there are reasonable grounds for insecurity.", w: "Under UCC 2-609, demand in writing — no response within 30 days can be repudiation." },
    { t: "Frustration of Purpose", d: "Excuses performance when an unforeseen event destroys the contract's main purpose.", w: "Rarely succeeds — courts require the purpose be shared and the event truly unforeseeable." },
    { t: "Impracticability", d: "Excuses performance made extremely difficult or costly by an unforeseen event.", w: "Increased cost alone almost never qualifies — draft a force majeure clause instead." },
    { t: "Impossibility", d: "Excuses performance when it has become objectively impossible.", w: "Applies to the task, not the party — 'I can't afford it' is not impossibility." },
    { t: "Condition Subsequent", d: "An event that, if it occurs, ends an existing duty to perform.", w: "Courts dislike forfeiture — state clearly that the duty terminates on the event." },
    { t: "Concurrent Conditions", d: "Performances that are due at the same time, each conditioned on the other.", w: "Common in closings — the party wanting to sue must tender its own performance." },
    { t: "Substantial Performance", d: "Performance close enough to the contract that payment is due, less damages for defects.", w: "Doesn't apply to express conditions — make critical requirements conditions if needed." },
    { t: "Perfect Tender Rule", d: "Under the UCC, a buyer may reject goods that fail to conform in any respect.", w: "Softened by the seller's right to cure and installment contract rules — read 2-508 and 2-612." },
    { t: "Rejection of Goods", d: "A buyer's refusal to accept goods that don't conform to the contract.", w: "Reject within a reasonable time and notify the seller, or the goods may be deemed accepted." },
    { t: "Revocation of Acceptance", d: "A buyer's withdrawal of acceptance of goods with defects that substantially impair value.", w: "Must happen within a reasonable time after discovery and before goods change condition." },
    { t: "Cover", d: "A buyer's purchase of substitute goods after a seller's breach.", w: "Recover the price difference — but buy in good faith and without unreasonable delay." },
    { t: "Battle of the Forms", d: "The clash between a buyer's purchase order terms and a seller's acknowledgment terms.", w: "UCC 2-207 may knock out conflicting terms — a signed master agreement avoids the fight." },
    { t: "Mirror Image Rule", d: "Common-law rule that an acceptance must exactly match the offer.", w: "Applies to services contracts — for goods, UCC 2-207 replaces it." },
    { t: "Click-Wrap", d: "An online agreement accepted by clicking 'I agree' after seeing the terms.", w: "Generally enforceable if the terms were reasonably presented — keep acceptance logs." },
    { t: "Browse-Wrap", d: "Online terms that claim to bind users just by using a site.", w: "Often unenforceable without actual or constructive notice — prefer click-wrap." },
    { t: "Shrink-Wrap", d: "License terms enclosed with a product, accepted by keeping or using it.", w: "Enforceability turns on notice and a chance to return — mostly superseded by click-wrap." },
    { t: "Unconscionability", d: "A court may refuse to enforce terms that are grossly unfair when made.", w: "Usually needs both procedural and substantive unfairness — watch consumer-facing terms." },
    { t: "Adhesion Contract", d: "A standard-form contract offered on a take-it-or-leave-it basis.", w: "Enforceable generally, but ambiguities and harsh terms get heightened scrutiny." },
    { t: "Implied Covenant of Good Faith", d: "Every contract carries an implied duty of good faith and fair dealing.", w: "It can't override express terms — but discretionary rights must be exercised honestly." },
    { t: "Course of Dealing", d: "A pattern of conduct between the parties in prior transactions.", w: "Can supply or explain terms — an integration clause doesn't always exclude it." },
    { t: "Course of Performance", d: "How the parties have actually performed under the current contract.", w: "Repeatedly accepting deviations can modify or waive terms — object in writing." },
    { t: "Usage of Trade", d: "A practice regularly observed in a particular industry.", w: "Can give words a specialized meaning — define terms if you don't want industry gloss." },
    { t: "Statute of Frauds", d: "Requires certain contracts, like those over one year or for goods of $500+, to be in writing.", w: "Emails may satisfy it — signature and writing requirements are easy to meet accidentally." },
    { t: "Mutual Mistake", d: "Both parties share a mistaken belief about a basic assumption of the contract.", w: "Can make the contract voidable — unless the contract allocated that risk to one side." },
    { t: "Unilateral Mistake", d: "Only one party is mistaken about a basic assumption of the contract.", w: "Rarely a defense — unless the other side knew or caused the mistake." },
    { t: "Rescission", d: "Unwinding a contract and restoring the parties to their pre-contract positions.", w: "Act promptly — delay or continued performance can ratify the contract." },
    { t: "Reformation", d: "A court rewrites a document to reflect the parties' actual agreement.", w: "Requires clear proof of a shared intent the writing failed to capture." },
    { t: "Ratification", d: "Approving a prior act that was not authorized, making it binding.", w: "Accepting benefits of an unauthorized contract can ratify it — object quickly." },
    { t: "Duress", d: "Improper threats that leave a party no reasonable alternative but to agree.", w: "Hard bargaining isn't duress — wrongful threats are. Keep negotiations civil and documented." },
    { t: "Undue Influence", d: "Unfair persuasion by someone in a position of trust or dominance.", w: "Rare in commercial deals — more relevant when individuals sign with advisers present." },
    { t: "Fraudulent Inducement", d: "Being tricked into a contract by false statements of fact.", w: "Non-reliance clauses can defeat it in many states — read them before signing." },
    { t: "Non-Reliance Clause", d: "Each party confirms it did not rely on statements outside the contract.", w: "In Delaware, it must be clear and affirmative to bar extra-contractual fraud claims." },
    { t: "Sandbagging", d: "Closing a deal despite knowing a rep is false, then suing for breach.", w: "State law varies — add a pro- or anti-sandbagging clause rather than leave it open." },
    { t: "Basket", d: "A loss threshold that must be met before indemnity claims are payable.", w: "Know whether it's a deductible or tipping basket — the economics differ sharply." },
    { t: "Escrow", d: "Funds or documents held by a neutral party until conditions are met.", w: "Spell out release triggers and joint instruction mechanics to avoid deadlock." },
    { t: "Holdback", d: "Part of the price retained by the buyer to secure post-closing obligations.", w: "Unlike escrow, the buyer holds the money — set clear release dates and dispute rules." },
    { t: "Earn-Out", d: "Additional purchase price paid if the business hits future milestones.", w: "Fertile ground for disputes — define metrics and the buyer's operating covenants." },
    { t: "Set-Off", d: "Deducting amounts owed to you from amounts you owe the other party.", w: "Silent contracts may allow it by law — expressly permit or prohibit it." },
    { t: "Recoupment", d: "Reducing a claim by amounts arising from the same transaction.", w: "Survives bankruptcy better than set-off — tie offsets to the same contract." },
    { t: "Acceleration Clause", d: "Makes all future payments due immediately on default.", w: "Require notice and cure first — automatic acceleration can surprise everyone." },
    { t: "Termination for Convenience", d: "Allows a party to end the contract without cause, usually on notice.", w: "Pair it with payment for work done and wind-down costs, or it can be very one-sided." },
    { t: "Termination for Cause", d: "Allows ending the contract because of the other party's breach or default.", w: "Define 'cause' and tie it to notice and cure — vague triggers invite litigation." },
    { t: "Evergreen Clause", d: "Automatically renews the contract for successive terms unless notice is given.", w: "Calendar the non-renewal notice window — missing it locks you in for another term." },
    { t: "Wind-Down Period", d: "A transition period after termination to complete orders or migrate services.", w: "Specify pricing, service levels and data return during the wind-down." },
    { t: "Step-In Rights", d: "A customer's right to take over performance when a supplier fails.", w: "Address access to staff, systems and subcontractors — otherwise the right is theoretical." },
    { t: "Most Favored Nation", d: "A promise to give a party terms at least as good as those given to others.", w: "Define comparable customers and audit rights — MFNs can also raise antitrust issues." },
    { t: "Right of First Refusal", d: "The right to match a third-party offer before the owner accepts it.", w: "Specify the matching period and what counts as a bona fide offer." },
    { t: "Right of First Negotiation", d: "The right to negotiate exclusively for a period before the owner talks to others.", w: "Weaker than a ROFR — nothing forces a deal, so set a clear exclusivity window." },
    { t: "Change of Control", d: "A transfer of ownership or control of a party, often by merger or share sale.", w: "Often triggers consent or termination rights — check whether it counts as assignment." },
    { t: "Key Person Clause", d: "Requires specific individuals to remain involved in performing the contract.", w: "Name the role as well as the person, and add replacement approval rights." },
    { t: "Non-Solicitation", d: "A promise not to recruit the other party's employees or customers.", w: "Carve out general job ads — and check state limits, since some treat it like a non-compete." },
    { t: "No-Hire Clause", d: "A promise not to employ the other party's personnel for a period.", w: "Broader than non-solicit and under antitrust scrutiny — keep it narrow and ancillary." },
    { t: "Background IP", d: "Intellectual property a party owned or developed before or outside the agreement.", w: "Define it by date and scope — and grant only the license needed to use the deliverables." },
    { t: "Foreground IP", d: "Intellectual property created during performance of the agreement.", w: "Ownership defaults vary — state who owns it, not just who 'may use' it." },
    { t: "Arising IP", d: "IP generated from activities under a research or services agreement.", w: "Watch for joint inventions — decide ownership and patent prosecution control upfront." },
    { t: "Work Made for Hire", d: "Copyright work owned by the commissioning party from creation, not the author.", w: "Only certain categories qualify for contractors — always back it up with an assignment." },
    { t: "Present Assignment", d: "'Hereby assigns' — transfers IP rights now, including future rights when created.", w: "'Agrees to assign' is only a promise — courts have let IP slip away over that wording." },
    { t: "Moral Rights", d: "An author's rights of attribution and integrity, strong outside the US.", w: "Add a waiver to the extent permitted by law — some countries don't allow full waiver." },
    { t: "Exclusive License", d: "A license granting rights to one licensee, excluding even the licensor.", w: "Say whether the licensor keeps rights to practice — 'sole' and 'exclusive' differ." },
    { t: "Sole License", d: "A license where only the licensee and the licensor may use the rights.", w: "Not a US term of art — define it to avoid confusion with exclusive." },
    { t: "Non-Exclusive License", d: "Permission to use rights that the licensor may also grant to others.", w: "Generally not assignable without consent under US federal IP law — address transfer." },
    { t: "Sublicense", d: "A license granted by a licensee to a third party under its own license.", w: "Require sublicenses to be written and consistent, and to terminate with the main license." },
    { t: "Field of Use", d: "Restricts a license to a particular product area, market or application.", w: "Define fields precisely — overlapping fields cause turf wars between licensees." },
    { t: "Territory", d: "The geographic area where licensed or distribution rights may be exercised.", w: "Online sales blur territories — address internet sales and export rules expressly." },
    { t: "Royalty", d: "A payment to a licensor based on use or sales of licensed rights.", w: "Define the royalty base and when royalties end — patent expiry matters." },
    { t: "Running Royalty", d: "A royalty paid continuously as a percentage of sales or per unit.", w: "Pair with audit rights and clear reporting periods." },
    { t: "Royalty Stacking", d: "Owing multiple royalties to different licensors on the same product.", w: "Negotiate an anti-stacking reduction with a floor so total royalty burden stays viable." },
    { t: "Net Sales", d: "Gross sales less specified deductions, used as the royalty base.", w: "List deductions exhaustively and cap them — vague deductions shrink royalties." },
    { t: "Minimum Annual Royalty", d: "A guaranteed yearly royalty payment regardless of actual sales.", w: "Clarify whether earned royalties credit against it and what happens if missed." },
    { t: "Upfront Fee", d: "A one-time payment due on signing a license or collaboration.", w: "State it is non-refundable and non-creditable if that's the deal." },
    { t: "Milestone Payment", d: "A payment triggered by achieving a defined development or commercial event.", w: "Define each milestone objectively — 'success' is not a milestone." },
    { t: "Patent Exhaustion", d: "The first authorized sale of a patented item ends the patentee's control over it.", w: "Post-sale restrictions can't be enforced through patent law — use contract terms instead." },
    { t: "First Sale Doctrine", d: "The owner of a lawful copy may resell or dispose of it without the copyright owner's permission.", w: "Software is often licensed, not sold, to avoid it — say so expressly." },
    { t: "Prior Art", d: "Existing public knowledge that may make a claimed invention not new or obvious.", w: "Keep pre-filing disclosures under NDA — your own publication can become prior art." },
    { t: "Grace Period", d: "Time after public disclosure during which a patent can still be filed.", w: "The US allows one year; most countries allow none — file before disclosing." },
    { t: "Freedom to Operate", d: "Assurance that a product can be made and sold without infringing others' rights.", w: "An FTO opinion is a snapshot — don't warrant it in a contract without a knowledge qualifier." },
    { t: "Patent Prosecution", d: "The process of obtaining a patent from a patent office.", w: "Assign control, cost-sharing and step-in rights — especially for jointly owned inventions." },
    { t: "Patent Maintenance", d: "Paying periodic fees to keep issued patents in force.", w: "Specify who pays and give notice before abandoning, so the other side can step in." },
    { t: "Inventorship", d: "Identifies who conceived the claimed invention — determined by patent law, not contract.", w: "Contracts can allocate ownership but cannot change who the true inventors are." },
    { t: "Joint Ownership", d: "Two or more parties own the same IP.", w: "In the US each joint patent owner can exploit and license without the other's consent." },
    { t: "Grant-Back", d: "A licensee's obligation to license or assign improvements back to the licensor.", w: "Exclusive grant-backs can raise antitrust concerns — non-exclusive is safer." },
    { t: "Improvements", d: "Modifications or enhancements to licensed technology.", w: "Define them narrowly — 'related to' can sweep in a licensee's independent work." },
    { t: "Trade Secret", d: "Information that has value because it is secret and is reasonably protected.", w: "Protection lasts only as long as secrecy — NDAs and access controls are the evidence." },
    { t: "Know-How", d: "Practical, often unpatented technical knowledge and experience.", w: "Hard to return once disclosed — license it with clear use limits and residual terms." },
    { t: "Trademark License", d: "Permission to use a trademark on specified goods or services.", w: "Include quality control — an uncontrolled 'naked license' can forfeit the mark." },
    { t: "Naked License", d: "A trademark license without quality control by the owner.", w: "Can lead to abandonment of the mark — always reserve inspection and approval rights." },
    { t: "Copyright", d: "Protects original works of authorship like code, text and images from copying.", w: "Protects expression, not ideas — data compilations get thin protection." },
    { t: "Derivative Work", d: "A new work based on and adapting a pre-existing copyrighted work.", w: "Address who owns derivatives of licensed materials, or the default rules decide." },
    { t: "Open Source License", d: "A license allowing free use, modification and sharing of source code under conditions.", w: "Copyleft terms can force disclosure of your code — require an open source schedule." },
    { t: "Copyleft", d: "An open source condition requiring derivatives to be shared under the same license.", w: "GPL-family components in distributed products need careful review." },
    { t: "Source Code Escrow", d: "Deposit of source code with a third party, released on triggers like vendor insolvency.", w: "Require verification testing — an unbuildable deposit is worthless." },
    { t: "Reverse Engineering", d: "Analyzing a product to discover how it works.", w: "Generally lawful for trade secrets — ban it by contract if you need to prevent it." },
    { t: "Residuals Clause", d: "Lets recipients use information retained in unaided memory.", w: "Can swallow an NDA — exclude patents, trade secrets and deliberate memorization." },
    { t: "Confidential Information", d: "Non-public information disclosed under an obligation of secrecy.", w: "Marking requirements can backfire — add 'or reasonably understood to be confidential'." },
    { t: "Standard Exclusions", d: "Information that's public, already known, independently developed or received from others.", w: "Put the burden of proof on the recipient and require written records." },
    { t: "Compelled Disclosure", d: "Disclosure of confidential information required by law or court order.", w: "Require prompt notice and cooperation so the discloser can seek a protective order." },
    { t: "Need to Know", d: "Limits disclosure to people who require the information for the stated purpose.", w: "Make the recipient liable for its representatives' breaches." },
    { t: "Permitted Purpose", d: "The specific purpose for which confidential information may be used.", w: "Define it narrowly — a vague purpose turns an NDA into a license." },
    { t: "Return or Destroy", d: "Obligation to return or destroy confidential information on request or termination.", w: "Allow archival backup copies, subject to continuing confidentiality." },
    { t: "Mutual NDA", d: "A non-disclosure agreement where both parties share and protect information.", w: "Check that obligations really are symmetric — one-way terms hide in mutual forms." },
    { t: "Unilateral NDA", d: "An NDA where only one party discloses information.", w: "If you're disclosing, don't use the other side's one-way form in reverse." },
    { t: "Standstill", d: "Prevents a party from acquiring the other's shares or making unsolicited bids for a time.", w: "Common in public-company NDAs — watch for 'don't ask, don't waive' terms." },
    { t: "DTSA Immunity Notice", d: "A notice of whistleblower immunity under the US Defend Trade Secrets Act.", w: "Omit it from employee or contractor agreements and you lose exemplary damages and fees." },
    { t: "Clean Team", d: "A restricted group allowed access to competitively sensitive information.", w: "Essential when sharing with competitors — document membership and firewalls." },
    { t: "Personal Data", d: "Information relating to an identified or identifiable individual.", w: "Under GDPR the definition is broad — pseudonymized data still counts." },
    { t: "Personal Information", d: "US state-law term for data that identifies or relates to a consumer or household.", w: "CCPA's definition reaches households and inferences — not just names and emails." },
    { t: "Data Controller", d: "Under GDPR, the entity that decides why and how personal data is processed.", w: "Being labeled 'processor' doesn't settle it — actual decision-making does." },
    { t: "Data Processor", d: "Under GDPR, an entity that processes personal data on behalf of a controller.", w: "Article 28 requires specific contract terms — use a compliant DPA." },
    { t: "Service Provider", d: "Under the CCPA, a business that processes personal information for another's business purpose.", w: "Contracts need prescribed restrictions or the transfer can be treated as a sale." },
    { t: "Data Processing Agreement", d: "A contract setting the terms on which a processor handles personal data.", w: "Check sub-processor approval, audit rights and breach notice timing." },
    { t: "Sub-Processor", d: "A third party engaged by a processor to process personal data.", w: "Require notice and an objection right, plus flow-down of data protection terms." },
    { t: "Standard Contractual Clauses", d: "EU-approved model terms for transferring personal data outside the EEA.", w: "Don't edit the clauses — add a transfer impact assessment and supplementary measures." },
    { t: "Cross-Border Transfer", d: "Moving personal data from one country to another.", w: "Map where data flows, including remote access — viewing can count as a transfer." },
    { t: "Data Breach", d: "Unauthorized access to or disclosure of personal or confidential data.", w: "Define notice timing in hours, and say who controls notifications to individuals." },
    { t: "Breach Notification", d: "The duty to tell regulators, customers or individuals about a data breach.", w: "GDPR gives controllers 72 hours — processor deadlines must leave room for that." },
    { t: "Data Subject Rights", d: "Individuals' rights to access, correct, delete or port their personal data.", w: "Require the processor to assist and to forward requests promptly." },
    { t: "Lawful Basis", d: "Under GDPR, the legal ground for processing personal data, such as consent or contract.", w: "Pick it before collecting — switching bases later is generally not allowed." },
    { t: "Legitimate Interests", d: "A GDPR lawful basis where processing is necessary and not overridden by individuals' rights.", w: "Document a balancing test — it's not available for every purpose." },
    { t: "Pseudonymization", d: "Replacing identifiers so data can't be attributed to a person without extra information.", w: "Still personal data under GDPR — keep the key separate and controlled." },
    { t: "Anonymization", d: "Irreversibly processing data so individuals can no longer be identified.", w: "A high bar — aggregated or coded data often isn't truly anonymous." },
    { t: "De-Identification", d: "Under HIPAA, removing identifiers via Safe Harbor or Expert Determination.", w: "Contract against re-identification attempts by recipients." },
    { t: "Protected Health Information", d: "Under HIPAA, individually identifiable health information held by covered entities or associates.", w: "Not all health data is PHI — consumer apps may fall under other laws." },
    { t: "Business Associate Agreement", d: "A HIPAA-required contract with a vendor handling PHI for a covered entity.", w: "Required before PHI changes hands — no BAA, no data." },
    { t: "Data Minimization", d: "Collecting and keeping only the personal data needed for the purpose.", w: "Build it into the statement of work — fewer fields means less breach exposure." },
    { t: "Purpose Limitation", d: "Personal data collected for one purpose shouldn't be used for incompatible ones.", w: "Secondary research use often needs fresh consent or a separate legal basis." },
    { t: "Retention Period", d: "How long data or records must or may be kept.", w: "Clinical and regulatory records may need years — reconcile with deletion duties." },
    { t: "Data Ownership", d: "Contractual allocation of rights in data generated or provided under a deal.", w: "Data isn't neatly 'owned' by law — specify use rights and restrictions instead." },
    { t: "Aggregated Data", d: "Data combined so that no individual or customer can be identified.", w: "Vendors often reserve rights to use it — define it tightly and ban re-identification." },
    { t: "Security Incident", d: "An event that compromises or may compromise the security of systems or data.", w: "Broader than breach — limit notice duties to confirmed incidents to avoid noise." },
    { t: "SOC 2 Report", d: "An independent audit report on a service organization's security and related controls.", w: "Ask for Type II, which tests controls over time, and review carve-outs and exceptions." },
    { t: "Sensitive Personal Data", d: "Special categories such as health, genetic, biometric or racial data.", w: "Higher consent and security standards apply — flag it in the data schedule." },
    { t: "Opt-In Consent", d: "Affirmative agreement before data is collected or used.", w: "Pre-checked boxes don't count under GDPR — keep records of how consent was obtained." },
    { t: "Opt-Out", d: "A right to stop processing, such as the sale or sharing of personal information.", w: "CCPA requires a clear opt-out link — honor browser-based signals where required." },
    { t: "Biometric Data", d: "Data from physical characteristics like fingerprints, face or voice.", w: "Illinois BIPA allows private suits with statutory damages — get written consent first." },
    { t: "Privacy by Design", d: "Building data protection into products and processes from the start.", w: "A GDPR requirement — document design choices for consumer studies." },
    { t: "Data Protection Impact Assessment", d: "A GDPR risk assessment required for high-risk processing.", w: "Do it before launch — regulators expect it for large-scale sensitive data." },
    { t: "Right to Erasure", d: "An individual's right under GDPR to have personal data deleted in some cases.", w: "Not absolute — research and legal retention exemptions may apply." },
    { t: "Clinical Trial Agreement", d: "A contract between a sponsor and a site governing the conduct of a clinical study.", w: "Align it with the protocol and informed consent — conflicts usually resolve in the protocol's favor." },
    { t: "Sponsor", d: "The entity that initiates, manages or finances a clinical study.", w: "Sponsor regulatory duties can be transferred to a CRO only in writing." },
    { t: "Principal Investigator", d: "The individual responsible for conducting a study at a site.", w: "Have the PI acknowledge the agreement even if not a party." },
    { t: "Contract Research Organization", d: "A company that performs study tasks on a sponsor's behalf.", w: "Spell out which sponsor obligations transfer and who pays sites." },
    { t: "Protocol", d: "The document describing a study's objectives, design, methods and analysis.", w: "Make deviations a breach only when material, and require prompt reporting." },
    { t: "Protocol Amendment", d: "A formal change to an approved study protocol.", w: "Usually needs IRB approval before implementation — budget changes should follow." },
    { t: "Informed Consent", d: "A participant's voluntary agreement after being told the study's risks and benefits.", w: "Contract data-use rights can't exceed what the consent form allows." },
    { t: "Institutional Review Board", d: "A committee that reviews research to protect human subjects in the US.", w: "IRB approval is a condition precedent — no enrollment before it." },
    { t: "Ethics Committee", d: "The non-US counterpart of an IRB that reviews human research.", w: "Requirements differ by country — check local approval timelines." },
    { t: "Good Clinical Practice", d: "International ethical and scientific quality standards for clinical trials.", w: "Reference ICH E6 by name and version, since GCP guidance is updated." },
    { t: "Adverse Event", d: "Any untoward medical occurrence in a participant, whether or not caused by the product.", w: "Set reporting timelines in the contract consistent with the protocol and regulations." },
    { t: "Serious Adverse Event", d: "An adverse event causing death, hospitalization, disability or similar serious outcomes.", w: "Usually requires reporting within 24 hours of awareness — make that explicit." },
    { t: "Subject Injury", d: "Harm to a study participant caused by the study product or procedures.", w: "Sponsors typically pay reasonable medical costs — define exclusions like negligence carefully." },
    { t: "Investigator-Initiated Study", d: "A study designed and run by an investigator, often with company funding or product.", w: "The company supports but doesn't sponsor — keep control language consistent with that." },
    { t: "Investigational Product", d: "The drug, device or product being tested in a study.", w: "Require return or destruction of unused product and accountability records." },
    { t: "Case Report Form", d: "The document used to record each participant's study data.", w: "Define data ownership and source-document access for monitors." },
    { t: "Source Documents", d: "Original records, like medical charts, where study data first appears.", w: "Grant monitor and auditor access while protecting other patients' privacy." },
    { t: "Monitoring", d: "Sponsor oversight of a study to verify data quality and compliance.", w: "Include remote monitoring rights and reasonable notice for site visits." },
    { t: "Site Audit", d: "A sponsor or regulator inspection of a study site's conduct and records.", w: "Require prompt notice of regulatory inspections and a chance to attend." },
    { t: "Publication Rights", d: "An investigator's right to publish study results, subject to sponsor review.", w: "Typical review is 30-60 days plus a short delay for patent filing — not a veto." },
    { t: "Multi-Site Publication", d: "Rule that results from a multi-center trial are published together first.", w: "Set a deadline after which individual sites may publish." },
    { t: "Trial Registration", d: "Posting study details on a public registry like ClinicalTrials.gov.", w: "Assign who registers and reports results — penalties apply for missed deadlines." },
    { t: "Study Budget", d: "The negotiated payment schedule for performing study procedures.", w: "Pay per completed visit and specify holdbacks, screen failures and invoiceable items." },
    { t: "Screen Failure", d: "A participant who is screened but doesn't qualify for the study.", w: "Decide upfront whether and how much screen failures are paid." },
    { t: "Enrollment Target", d: "The number of participants a site agrees to try to enroll.", w: "Make it a target, not a guarantee, and allow termination for under-enrollment." },
    { t: "Fair Market Value", d: "Compensation consistent with arm's-length rates for the services performed.", w: "Required for investigator payments to avoid anti-kickback issues — document the basis." },
    { t: "Sunshine Act", d: "US law requiring manufacturers to report certain payments to physicians and hospitals.", w: "Have sites acknowledge reporting — payments under research contracts are disclosed." },
    { t: "Anti-Kickback Statute", d: "US federal law barring payments to induce referrals of federally reimbursed business.", w: "Applies to healthcare deals — structure payments for legitimate services only." },
    { t: "Material Transfer Agreement", d: "A contract governing transfer of research materials like samples or compounds.", w: "Address derivatives, publications and whether commercial use needs a separate license." },
    { t: "Biological Samples", d: "Human tissue, blood or other specimens collected for research.", w: "Future use must match consent — address storage, export and destruction." },
    { t: "Sponsored Research Agreement", d: "A contract funding research at a university or institution.", w: "Universities insist on publication rights and limited warranties — plan for both." },
    { t: "Option to License", d: "A right to negotiate or obtain a license to research results within a set period.", w: "Specify the option period, exercise mechanics and fallback if terms aren't agreed." },
    { t: "Bayh-Dole Act", d: "US law letting institutions own inventions made with federal funding.", w: "Government keeps a license and march-in rights — check funding before licensing." },
    { t: "March-In Rights", d: "The US government's right to require licensing of federally funded inventions.", w: "Rarely used but real — disclose federal funding in license reps." },
    { t: "Consumer Study", d: "Research testing products or perceptions with members of the public.", w: "Confirm consent, compensation and data handling — consumer law and privacy rules apply." },
    { t: "Home Use Test", d: "A study where participants use a product at home and report back.", w: "Address product safety, adverse reactions and what happens to unused product." },
    { t: "Panelist", d: "A participant in a consumer or sensory research study.", w: "Keep panelist data minimal and pseudonymized when shared with the sponsor." },
    { t: "Claims Substantiation", d: "Evidence supporting advertising claims about a product.", w: "Study design must support the exact claim — ownership of the data matters too." },
    { t: "Testimonial", d: "A consumer's statement endorsing a product, used in advertising.", w: "FTC rules require disclosure of material connections, like payment or free product." },
    { t: "Incentive", d: "Payment or gift given to research participants for their time.", w: "Keep it modest and non-coercive — large incentives can concern ethics boards." },
    { t: "Statement of Work", d: "A document describing specific tasks, deliverables and timelines under a master agreement.", w: "State that the master agreement prevails unless the SOW expressly overrides it." },
    { t: "Master Services Agreement", d: "A framework contract with general terms for future service orders.", w: "Negotiate the MSA hard once — each SOW then needs only commercial details." },
    { t: "Order of Precedence", d: "A clause ranking documents to resolve conflicts between them.", w: "Check that a purchase order's terms can't jump to the top of the list." },
    { t: "Deliverables", d: "The specific work product a party must provide under the contract.", w: "Tie payment to acceptance of defined deliverables, not just effort." },
    { t: "Acceptance Testing", d: "A process for the customer to verify that deliverables meet specifications.", w: "Add deemed acceptance after a set period, plus a re-test and rejection path." },
    { t: "Deemed Acceptance", d: "Deliverables count as accepted if the customer doesn't reject them in time.", w: "Customers should push for a longer window — vendors want it short." },
    { t: "Change Order", d: "A written document modifying scope, price or schedule.", w: "Require signed change orders — informal scope creep is hard to bill or resist." },
    { t: "Service Level Agreement", d: "Measurable performance standards for a service, like uptime or response time.", w: "Define how levels are measured and excluded downtime." },
    { t: "Service Credits", d: "Fee reductions given when service levels are missed.", w: "Say whether credits are the sole remedy — vendors usually want them to be." },
    { t: "Net 30", d: "Payment due 30 days after the invoice date.", w: "Clarify from invoice date or receipt — and whether disputed amounts can be withheld." },
    { t: "Late Payment Interest", d: "Interest charged on overdue amounts.", w: "Keep the rate below state usury limits — 1.5% a month can exceed them." },
    { t: "Disputed Invoice", d: "An invoice the customer challenges in good faith.", w: "Require payment of undisputed amounts and a written dispute notice." },
    { t: "Price Escalation", d: "A clause allowing price increases over time or on cost changes.", w: "Tie increases to an index like CPI and cap annual changes." },
    { t: "Take-or-Pay", d: "Buyer must either take a minimum quantity or pay for it anyway.", w: "Treat it like a minimum purchase commitment — check if shortfalls roll over." },
    { t: "Requirements Contract", d: "Buyer agrees to purchase all its needs for a product from one seller.", w: "Under the UCC, quantities must not be unreasonably disproportionate to estimates." },
    { t: "Output Contract", d: "Seller agrees to sell its entire output to one buyer.", w: "Good-faith limits apply — sudden spikes in output may not be covered." },
    { t: "Purchase Order", d: "A buyer's document ordering goods or services, often with standard terms.", w: "Its fine-print terms can override yours — reference the governing master agreement." },
    { t: "Incoterms", d: "Standard trade terms defining delivery, risk and cost allocation for goods.", w: "Cite the version, such as Incoterms 2020 — they don't address title transfer." },
    { t: "FOB", d: "'Free on board' — a shipping term marking where risk passes to the buyer.", w: "Under the UCC and Incoterms it means different things — specify which you mean." },
    { t: "Risk of Loss", d: "Which party bears loss if goods are damaged or destroyed.", w: "Separate risk of loss from title — they don't have to pass together." },
    { t: "Title Transfer", d: "When ownership of goods passes from seller to buyer.", w: "State it expressly — defaults depend on delivery terms." },
    { t: "Consignment", d: "Goods delivered to another to sell while the owner keeps title.", w: "File a UCC financing statement or creditors of the consignee may take the goods." },
    { t: "Exclusivity", d: "A promise to deal only with one party for specified products or territory.", w: "Tie it to minimum performance — exclusivity without targets is a free option." },
    { t: "Minimum Purchase Commitment", d: "A buyer's promise to buy at least a set quantity or value.", w: "Specify the remedy for shortfall — price adjustment, payment or loss of exclusivity." },
    { t: "Forecast", d: "A non-binding estimate of future orders.", w: "Distinguish binding firm periods from rolling non-binding forecasts." },
    { t: "Lead Time", d: "The period between placing an order and delivery.", w: "Include it in the supply terms and link late delivery to remedies." },
    { t: "Allocation", d: "How a supplier divides limited supply among customers during shortages.", w: "Negotiate pro rata allocation based on historical purchases." },
    { t: "Warranty Disclaimer", d: "Exclusion of implied warranties, often in capital letters.", w: "Under UCC 2-316, a merchantability disclaimer must mention it and be conspicuous." },
    { t: "Merchantability", d: "An implied warranty that goods are fit for ordinary purposes.", w: "Arises automatically from merchant sellers — disclaim it conspicuously if needed." },
    { t: "Fitness for a Particular Purpose", d: "An implied warranty that goods suit a buyer's specific, known purpose.", w: "Arises when the buyer relies on seller expertise — disclaim in writing." },
    { t: "Warranty of Non-Infringement", d: "A promise that a product doesn't infringe third-party IP.", w: "Sellers often limit it to knowledge or specific countries — buyers resist." },
    { t: "Audit Rights", d: "The right to inspect another party's books and records.", w: "Limit frequency, set notice periods, and shift costs if errors exceed a threshold." },
    { t: "Records Retention", d: "The obligation to keep books and records for a set period.", w: "Match it to audit rights and regulatory periods — they should line up." },
    { t: "Insurance Requirements", d: "Minimum insurance coverage a party must carry.", w: "Require certificates and additional-insured status — not just a dollar figure." },
    { t: "Additional Insured", d: "A party added to another's insurance policy for coverage.", w: "Ask for primary and non-contributory language so their policy pays first." },
    { t: "Subrogation Waiver", d: "Prevents an insurer from suing the other party after paying a claim.", w: "Confirm the insurance policy permits the waiver." },
    { t: "Subcontracting", d: "Delegating part of the work to a third party.", w: "Require consent, flow-down terms and full responsibility for subcontractors." },
    { t: "Flow-Down Clause", d: "Requires a contractor to pass specified obligations to its subcontractors.", w: "Essential for data protection and government contract terms." },
    { t: "Delegation", d: "Transferring performance duties to another party.", w: "The delegating party usually stays liable — say so expressly." },
    { t: "Pass-Through Costs", d: "Third-party expenses billed to the customer at cost.", w: "Require receipts and advance approval over a threshold." },
    { t: "Gross-Up", d: "Increasing a payment so the recipient nets the same amount after taxes.", w: "Common for withholding taxes — confirm treaty benefits first." },
    { t: "Withholding Tax", d: "Tax a payer must deduct from payments, often on cross-border royalties.", w: "Allocate who bears it and require cooperation on treaty forms." },
    { t: "Pay-When-Paid", d: "Payment to a subcontractor is due when the contractor gets paid.", w: "Some states treat it as timing only — 'pay-if-paid' shifts risk more." },
    { t: "Letter of Intent", d: "A preliminary document outlining proposed deal terms.", w: "State which provisions are binding — otherwise courts may treat it all as binding." },
    { t: "Term Sheet", d: "A summary of key terms for a proposed transaction.", w: "Mark it non-binding except confidentiality, exclusivity and costs." },
    { t: "Agreement to Agree", d: "A promise to reach agreement on terms later.", w: "Usually unenforceable — but a duty to negotiate in good faith may be enforced." },
    { t: "Affiliate", d: "An entity that controls, is controlled by, or is under common control with a party.", w: "Define control and timing — does a later-acquired affiliate get the benefit?" },
    { t: "Subsidiary", d: "A company controlled by another company, usually through majority ownership.", w: "Not the same as affiliate — sister companies aren't subsidiaries." },
    { t: "Parent Guarantee", d: "A parent company's promise to cover its subsidiary's obligations.", w: "Get it when contracting with a thinly capitalized subsidiary." },
    { t: "Guaranty", d: "A promise to answer for another's debt or performance if they fail.", w: "Say 'guaranty of payment', not 'collection', so you don't have to sue the debtor first." },
    { t: "Authorized Signatory", d: "A person empowered to sign and bind an entity.", w: "Ask for an incumbency certificate on big deals — titles alone may mislead." },
    { t: "Apparent Authority", d: "Authority a third party reasonably believes an agent has, based on the principal's conduct.", w: "Can bind a company even without actual authority — control who signs." },
    { t: "Actual Authority", d: "Authority a principal has actually given an agent, expressly or impliedly.", w: "Delegation of authority policies define it internally." },
    { t: "Corporate Veil", d: "The separation shielding shareholders from a company's liabilities.", w: "Piercing is rare but possible — commingled funds and undercapitalization invite it." },
    { t: "Limited Liability Company", d: "A business entity combining limited liability with flexible management and tax treatment.", w: "Check whether it's member- or manager-managed before deciding who signs." },
    { t: "Good Standing", d: "Confirms an entity is properly registered and current on filings in its state.", w: "Get a good standing certificate when relying on an entity rep." },
    { t: "Successors and Assigns", d: "Makes the agreement binding on and benefiting parties' successors and permitted assigns.", w: "It doesn't itself permit assignment — check the anti-assignment clause." },
    { t: "Merger by Operation of Law", d: "A merger in which assets and contracts pass automatically to the surviving entity.", w: "Some courts treat it as an assignment — expressly address mergers." },
    { t: "Asset Purchase", d: "Buying selected assets of a business rather than its shares.", w: "Contracts need assignment or consent to transfer — check anti-assignment clauses." },
    { t: "Due Diligence", d: "Investigation of a party, business or asset before a transaction.", w: "Diligence findings can affect sandbagging and knowledge qualifiers." },
    { t: "Disclosure Schedule", d: "A schedule listing exceptions to reps and warranties.", w: "Generic disclosures may not qualify reps — be specific and cross-reference." },
    { t: "Material Adverse Effect", d: "A significant negative change in a business, often a closing condition.", w: "Courts set a high bar — define carve-outs like market-wide changes." },
    { t: "Knowledge Qualifier", d: "Limits a rep to what a party actually knows or should know.", w: "Define whose knowledge counts and whether reasonable inquiry is required." },
    { t: "Materiality Scrape", d: "Ignoring materiality qualifiers in reps when calculating indemnifiable losses.", w: "Double materiality scrapes are buyer-friendly — sellers often accept only one." },
    { t: "Bring-Down", d: "Confirmation at closing that reps remain true as of that date.", w: "Separates signing reps from closing reps — check the standard used." },
    { t: "Closing Conditions", d: "Requirements that must be met before a party is obliged to close.", w: "Distinguish waivable conditions from covenants that create liability." },
    { t: "Outside Date", d: "The date after which either party can terminate if closing hasn't occurred.", w: "Add an extension for pending regulatory approvals." },
    { t: "Arbitration", d: "Resolving disputes privately before an arbitrator instead of in court.", w: "Specify rules, seat, number of arbitrators and language — and that awards are final." },
    { t: "Seat of Arbitration", d: "The legal home of the arbitration, which sets the procedural law and court supervision.", w: "Not necessarily where hearings occur — choose an arbitration-friendly jurisdiction." },
    { t: "Mediation", d: "A non-binding process where a neutral helps parties reach settlement.", w: "Make it a pre-condition with a deadline so it can't delay urgent relief." },
    { t: "Escalation Clause", d: "Requires disputes to be raised to senior management before litigation.", w: "Set short time limits and carve out injunctive relief." },
    { t: "Expert Determination", d: "A binding decision on technical or financial issues by an independent expert.", w: "Good for royalty or accounting disputes — limit the scope to factual questions." },
    { t: "Baseball Arbitration", d: "Each side proposes a figure and the arbitrator must choose one.", w: "Encourages reasonable offers — works best for single-number disputes." },
    { t: "Class Action Waiver", d: "A promise not to bring claims as part of a class or collective action.", w: "Generally enforceable in arbitration agreements under the FAA." },
    { t: "Federal Arbitration Act", d: "US law making written arbitration agreements generally valid and enforceable.", w: "Preempts most state rules that single out arbitration." },
    { t: "New York Convention", d: "Treaty requiring member countries to recognize and enforce foreign arbitral awards.", w: "Why international arbitration awards often travel better than court judgments." },
    { t: "Interim Relief", d: "Temporary measures, like injunctions, pending the final resolution of a dispute.", w: "Preserve the right to seek it from courts even when arbitration applies." },
    { t: "Prevailing Party Fees", d: "The winning party recovers its attorneys' fees from the losing party.", w: "Departs from the American Rule — define 'prevailing' for partial wins." },
    { t: "American Rule", d: "Each party pays its own attorneys' fees unless a statute or contract says otherwise.", w: "Silence means no fee-shifting — add a clause if you want it." },
    { t: "Statute of Limitations", d: "The deadline for bringing a legal claim.", w: "Some states let contracts shorten it — others don't, and few allow lengthening." },
    { t: "Laches", d: "An equitable defense barring claims after unreasonable delay that prejudices the other side.", w: "Applies to equitable remedies like injunctions — don't wait to act." },
    { t: "Personal Jurisdiction", d: "A court's power over a particular party.", w: "Consent to jurisdiction in the forum clause avoids fights over it." },
    { t: "Service of Process", d: "Formal delivery of legal papers to start a lawsuit.", w: "Contracts can appoint an agent for service — useful for foreign parties." },
    { t: "Litigation Hold", d: "A directive to preserve documents relevant to anticipated litigation.", w: "Issue it as soon as a dispute is reasonably foreseeable." },
    { t: "Attorney-Client Privilege", d: "Protects confidential communications between lawyer and client for legal advice.", w: "Forwarding advice to the other side can waive it — mark and limit distribution." },
    { t: "Common Interest Doctrine", d: "Allows parties with a shared legal interest to share privileged material.", w: "Document it in a written common interest agreement." },
    { t: "Settlement Privilege", d: "Rule limiting use of settlement offers as evidence of liability.", w: "Federal Rule of Evidence 408 isn't absolute — label talks as settlement communications." },
    { t: "Without Prejudice", d: "Communications in settlement talks that can't be used as admissions.", w: "Mainly an English and Commonwealth concept — US protection is narrower." },
    { t: "Bona Fide", d: "'In good faith' — genuine, without fraud or deceit.", w: "'Bona fide offer' needs defining in ROFR clauses." },
    { t: "Bona Fide Purchaser", d: "A buyer for value without notice of competing claims.", w: "Can take free of some prior interests — record and perfect your rights." },
    { t: "De Minimis", d: "So minor it is disregarded by the law.", w: "Define a de minimis threshold for audits and notices to avoid trivial disputes." },
    { t: "Mutatis Mutandis", d: "'With the necessary changes' — applying a provision with conforming adjustments.", w: "Convenient but vague — write out the adapted terms when stakes are high." },
    { t: "Inter Alia", d: "'Among other things.'", w: "Often signals a non-exhaustive list — use 'including without limitation' instead." },
    { t: "Ab Initio", d: "'From the beginning.'", w: "'Void ab initio' means it never had effect — strong language for assignments." },
    { t: "Ultra Vires", d: "'Beyond the powers' — acts outside a corporation's legal authority.", w: "Largely limited for modern corporations — but relevant for some public bodies." },
    { t: "Nunc Pro Tunc", d: "'Now for then' — giving an act retroactive effect to an earlier date.", w: "Backdating a signature is risky — use a stated effective date instead of a false signing date." },
    { t: "Prima Facie", d: "'At first sight' — sufficient evidence unless rebutted.", w: "A certificate deemed prima facie evidence shifts the burden to challengers." },
    { t: "Res Judicata", d: "A final judgment bars relitigating the same claim between the same parties.", w: "Bring all related claims together or risk losing them." },
    { t: "Stare Decisis", d: "The principle that courts follow precedent from earlier decisions.", w: "A case from another state is persuasive only — check your governing law's courts." },
    { t: "Force of Law", d: "Having the same binding effect as a statute or regulation.", w: "Industry codes may lack it — incorporate them expressly if you need compliance." },
    { t: "Pro Rata", d: "In proportion — allocated according to a share.", w: "State the basis: days, revenue or units — 'pro rata' alone can be ambiguous." },
    { t: "Quid Pro Quo", d: "'Something for something' — an exchange of value.", w: "In negotiations, track concessions so each one buys something in return." },
    { t: "Ejusdem Generis", d: "General words after specific ones are limited to things of the same kind.", w: "Add 'without limitation' if a catch-all should reach beyond the listed category." },
    { t: "Expressio Unius", d: "Expressing one thing implies the exclusion of others.", w: "Lists of carve-outs may be read as exhaustive — add 'including' if not." },
    { t: "Noscitur a Sociis", d: "A word's meaning is known by the company it keeps.", w: "Ambiguous words in a list take color from their neighbors." },
    { t: "Plain Meaning Rule", d: "Clear, unambiguous contract words are given their ordinary meaning.", w: "Define terms you want to carry a special meaning." },
    { t: "Four Corners Rule", d: "Interpreting a document from its text alone without outside evidence.", w: "Draft so the document stands on its own — don't rely on emails." },
    { t: "Specific Over General", d: "A specific provision controls over a general one on the same subject.", w: "Use 'notwithstanding' expressly if a general clause should win." },
    { t: "Notwithstanding", d: "'Despite' — gives one provision priority over conflicting ones.", w: "Multiple notwithstanding clauses can collide — check which truly prevails." },
    { t: "Subject To", d: "Makes a provision subordinate to another.", w: "The mirror image of notwithstanding — use one or the other, not both." },
    { t: "Including Without Limitation", d: "Signals that a list is illustrative, not exhaustive.", w: "Add an interpretation clause so 'including' always means this." },
    { t: "Shall vs. Will", d: "'Shall' imposes an obligation; 'will' often states future intent or obligation.", w: "Pick one convention for obligations and apply it consistently." },
    { t: "May", d: "Grants a permission or discretion, not an obligation.", w: "Avoid 'may not' when you mean a prohibition — 'shall not' is clearer." },
    { t: "Reasonable Efforts", d: "A standard requiring sensible, good-faith attempts to achieve a result.", w: "Courts vary on how it compares to 'best' or 'commercially reasonable' — define it." },
    { t: "Best Efforts", d: "A demanding standard that may require a party to act beyond its own interest.", w: "Can mean significant expense — define or replace with a lower standard." },
    { t: "Commercially Reasonable Efforts", d: "Efforts a prudent business would use, considering its own interests.", w: "Define with benchmarks, such as efforts used for similar products." },
    { t: "Sole Discretion", d: "A party may decide for any reason, limited mainly by good faith.", w: "Pair with 'reasonable discretion' elsewhere to signal the difference." },
    { t: "Not Unreasonably Withheld", d: "Consent may be refused only for a reasonable reason.", w: "Add 'conditioned or delayed' to prevent stalling tactics." },
    { t: "Deemed", d: "Treats something as true for the contract's purposes, whether or not it is.", w: "Powerful — deemed notice or acceptance can bind parties who never saw it." },
    { t: "Defined Terms", d: "Capitalized words given a specific meaning in the agreement.", w: "Check every capitalized term is defined and used consistently." },
    { t: "Business Day", d: "A day other than a weekend or public holiday, as defined.", w: "Specify which jurisdiction's holidays — cross-border deals differ." },
    { t: "Calendar Day", d: "Every day of the week, including weekends and holidays.", w: "Say 'days' without a definition and you'll argue about which one." },
    { t: "Effective Date", d: "The date from which the agreement takes effect.", w: "May differ from signing — address work done before it." },
    { t: "Term", d: "The duration of the agreement.", w: "Spell out start, end and renewal — and what survives." },
    { t: "Execution", d: "Signing a contract to make it effective.", w: "Check that each signature block names the correct legal entity." },
    { t: "Electronic Signature", d: "An electronic symbol or process adopted with intent to sign.", w: "Valid under ESIGN and UETA — some documents, like wills, still need wet ink." },
    { t: "Notarization", d: "Certification by a notary of a signer's identity and signature.", w: "Some foreign filings and IP assignments need it — check before closing." },
    { t: "Apostille", d: "A certificate authenticating documents for use in Hague Convention countries.", w: "Allow time — foreign registrations of IP assignments may require it." },
    { t: "Side Letter", d: "A separate agreement supplementing or modifying a main contract.", w: "Can conflict with the integration clause — reference each other explicitly." },
    { t: "Lex Loci Contractus", d: "'The law of the place of contracting' — a traditional rule for choosing governing law.", w: "Many US states now apply a 'most significant relationship' test instead — choose the law expressly." },
  ];

  // ── Content: Trivia of the Day ────────────────────────────────────
  var TRIVIA = [
    { q: "In Leonard v. Pepsico, a man sued for the Harrier jet shown in a Pepsi Points ad. The court held the ad was…", a: ["An obvious joke — no offer", "A binding unilateral offer", "An invitation to negotiate only"], c: 0, x: "The court found no objective person could believe a $23M fighter jet came with 7,000,000 Pepsi Points. The 'offer' failed as a matter of law." },
    { q: "A missing Oxford comma in a Maine dairy's overtime statute famously cost the company about…", a: ["$5 million", "$50,000", "$500 million"], c: 0, x: "O'Connor v. Oakhurst Dairy (2017) — 'packing for shipment or distribution' was ambiguous without the comma; the case settled for $5M." },
    { q: "Carlill v. Carbolic Smoke Ball Co. established that a public ad promising payment can be…", a: ["A unilateral offer accepted by performance", "Mere puffery, never binding", "Valid only if individually addressed"], c: 0, x: "Mrs. Carlill used the smoke ball, caught influenza anyway, and the £100 reward was enforceable — the ad was an offer to the world." },
    { q: "Van Halen's contracts demanded a bowl of M&Ms with the brown ones removed. The clause's real purpose was…", a: ["A safety-compliance canary", "Pure rock-star ego", "A merchandising tie-in"], c: 0, x: "Buried in dense technical riders, brown M&Ms revealed whether the venue had actually read the safety specs for their massive stage rig." },
    { q: "Hadley v. Baxendale limits consequential damages to losses that were…", a: ["Foreseeable at contract formation", "Actually suffered, however remote", "Under £100"], c: 0, x: "The broken mill shaft case (1854) — special circumstances must be communicated up front, which is why limitation-of-liability clauses recite them." },
    { q: "Under the mailbox rule, an acceptance is generally effective when…", a: ["Dispatched", "Received", "Read"], c: 0, x: "Acceptance on dispatch; revocation on receipt. Modern contracts often override it by requiring notice to be 'effective on receipt.'" },
    { q: "The Statute of Frauds generally requires a writing for contracts that cannot be performed within…", a: ["One year", "Six months", "Thirty days"], c: 0, x: "The one-year rule is read narrowly: if performance within a year is conceivably possible, no writing is required." },
    { q: "The UCC's 'battle of the forms' provision is…", a: ["§ 2-207", "§ 1-103", "§ 9-401"], c: 0, x: "It decides whose boilerplate wins when purchase orders and acknowledgments conflict — and why 'last shot' doctrine faded for goods." },
    { q: "A liquidated damages clause is unenforceable when a court finds it operates as…", a: ["A penalty", "An estimate", "A cap"], c: 0, x: "The test: reasonable forecast of hard-to-measure harm at formation. In terrorem amounts get struck." },
    { q: "Specific performance is most readily granted for contracts involving…", a: ["Land and unique goods", "Commodity sales", "Employment services"], c: 0, x: "Money damages suffice for fungibles; uniqueness makes them inadequate. Courts won't order people to work — that's involuntary servitude territory." },
    { q: "The parol evidence rule bars…", a: ["Prior agreements contradicting an integrated writing", "All oral testimony in contract cases", "Evidence of fraud"], c: 0, x: "It protects final writings from being rewritten by negotiation history — but fraud, ambiguity, and condition-precedent evidence still come in." },
    { q: "'Four corners' interpretation means a court looks…", a: ["Only at the document itself", "At industry custom first", "At the parties' emails"], c: 0, x: "If the writing is unambiguous, extrinsic evidence stays out. Ambiguity is the doorway through which everything else enters." },
    { q: "An option contract differs from a plain offer because it…", a: ["Is supported by consideration and irrevocable", "Must be in writing", "Cannot expire"], c: 0, x: "Paying to hold an offer open makes revocation a breach. Without consideration, offers are freely revocable before acceptance." },
    { q: "In contract law, a 'peppercorn' refers to…", a: ["Nominal but sufficient consideration", "A minor breach", "A boilerplate clause"], c: 0, x: "Courts don't weigh the adequacy of consideration — a peppercorn will do, which is why $1 recitals persist." },
    { q: "The 'mirror image' rule requires that an acceptance…", a: ["Match the offer exactly", "Be in the same medium as the offer", "Be notarized"], c: 0, x: "Any variation makes it a counteroffer at common law. The UCC relaxed this for goods — hence § 2-207's existence." },
    { q: "Promissory estoppel allows enforcement of a promise without…", a: ["Consideration", "Reliance", "A promisor"], c: 0, x: "Reasonable, detrimental reliance substitutes for the bargain. It's the safety net under gratuitous promises." },
    { q: "A contract signed under economic duress is…", a: ["Voidable by the coerced party", "Automatically void", "Fully enforceable"], c: 0, x: "Voidable, not void — the victim chooses whether to rescind, and ratification by performance can waive the defense." },
    { q: "'Efficient breach' theory says a party should breach when…", a: ["Paying damages costs less than performing", "The other side breaches first", "A better lawyer is available"], c: 0, x: "Law-and-economics' most provocative idea: expectation damages make some breaches socially efficient. Liquidated damages clauses push back." },
    { q: "In Hawkins v. McGee, the 'hairy hand' case, damages were measured by the difference between…", a: ["The promised hand and the hand received", "The hand before and after surgery", "The fee charged and a fair fee"], c: 0, x: "New Hampshire, 1929: a surgeon guaranteed a '100% perfect hand.' Expectation damages compare what was promised with what was delivered." },
    { q: "In Lucy v. Zehmer, a farm sale scribbled on a restaurant check was enforced despite the seller's claim that…", a: ["He was only joking", "He could not read", "The check was unsigned"], c: 0, x: "Virginia, 1954: under the objective theory, outward words and conduct control. An undisclosed jest doesn't undo a serious-seeming deal." },
    { q: "In Hamer v. Sidway, a nephew earned $5,000 from his uncle by…", a: ["Giving up drinking, smoking and gambling until 21", "Running the family farm", "Graduating from college"], c: 0, x: "New York, 1891: giving up a legal right is valid consideration, even if the forbearance actually benefits the promisee." },
    { q: "Raffles v. Wichelhaus collapsed because the cotton was to arrive on a ship named 'Peerless' and…", a: ["Two ships bore that name", "The ship sank", "The ship was renamed"], c: 0, x: "Court of Exchequer, 1864: each side meant a different Peerless sailing from Bombay, so there was no meeting of the minds." },
    { q: "Sherwood v. Walker, the classic mutual mistake case, involved the sale of…", a: ["A cow thought to be barren", "A painting thought to be a fake", "A diamond thought to be glass"], c: 0, x: "Rose 2d of Aberlone turned out to be pregnant. Michigan allowed rescission because the mistake went to the very nature of the thing sold (1887)." },
    { q: "In Wood v. Boston, a woman sold a small stone for $1 that turned out to be…", a: ["An uncut diamond", "A meteorite", "A Roman coin"], c: 0, x: "Wisconsin, 1885: neither side knew what the stone was, so the sale stood. Both had bargained under conscious uncertainty." },
    { q: "In Wood v. Lucy, Lady Duff-Gordon, Judge Cardozo saved an exclusive agency deal by implying a promise to…", a: ["Use reasonable efforts", "Pay a minimum royalty", "Give 30 days' notice"], c: 0, x: "New York, 1917: the whole writing was 'instinct with an obligation.' The fashion designer's exclusive agent had to try to market her name." },
    { q: "In Jacob & Youngs v. Kent, the builder used the wrong brand of pipe. The brand the contract required was…", a: ["Reading", "Cohoes", "Pittsburgh"], c: 0, x: "Cardozo held the builder had substantially performed. Damages were the difference in value (nominal), not the cost of tearing out walls." },
    { q: "In Peevyhouse v. Garland Coal, farmers got only $300 instead of the roughly $29,000 needed to…", a: ["Restore their strip-mined land", "Rebuild their barn", "Replace their cattle"], c: 0, x: "Oklahoma, 1962: where repair cost is grossly disproportionate to the gain in value, damages may be limited to the diminution in value." },
    { q: "Groves v. John Wunder Co. awarded the cost of completing performance even though the land was worth…", a: ["Far less than the cost of the work", "More after the breach", "Nothing at all"], c: 0, x: "Minnesota, 1939: about $60,000 to regrade land worth about $12,000. A wilful breacher couldn't pocket the savings." },
    { q: "Williams v. Walker-Thomas Furniture involved a clause letting the store repossess every item bought if…", a: ["Any balance remained on any purchase", "The buyer moved house", "Prices rose"], c: 0, x: "D.C. Circuit, 1965: absence of meaningful choice plus unreasonably favourable terms can make a clause unconscionable and unenforceable." },
    { q: "In Mills v. Wyman, a father's promise to repay a stranger who had nursed his adult son was unenforceable because…", a: ["Moral obligation is not consideration", "The son was a minor", "It was not in writing"], c: 0, x: "Massachusetts, 1825: the care came before the promise, so it was past consideration. The promise was gratuitous." },
    { q: "Webb v. McGowin enforced a promise to pay a worker who was crippled while…", a: ["Saving the promisor from a falling block", "Rescuing the promisor's child", "Fighting a mill fire"], c: 0, x: "Alabama, 1935: the material-benefit rule. A promise made in recognition of a benefit already received may be enforced." },
    { q: "Ricketts v. Scothorn enforced a grandfather's promissory note because his granddaughter relied on it by…", a: ["Quitting her job", "Buying a house", "Moving abroad"], c: 0, x: "Nebraska, 1898: an early estoppel case and a forerunner of the Restatement's reliance principle in Section 90." },
    { q: "Hoffman v. Red Owl Stores applied promissory estoppel to…", a: ["Failed franchise negotiations", "A charitable pledge", "A promise of marriage"], c: 0, x: "Wisconsin, 1965: Hoffman sold his bakery and moved on Red Owl's assurances. Reliance damages were allowed though no contract was formed." },
    { q: "Drennan v. Star Paving held that a subcontractor's bid could not be revoked once…", a: ["The general contractor relied on it in its own bid", "The project was finished", "It was formally accepted"], c: 0, x: "California, 1958 (Justice Traynor): reliance made the paving bid irrevocable, in contrast to Learned Hand's earlier view in James Baird v. Gimbel." },
    { q: "In James Baird Co. v. Gimbel Bros., Judge Learned Hand let a supplier withdraw a mistaken price quote for…", a: ["Linoleum", "Steel beams", "Window glass"], c: 0, x: "Second Circuit, 1933: the offer sought an acceptance, not reliance, so it remained revocable until accepted." },
    { q: "In Alaska Packers' Ass'n v. Domenico, fishermen who demanded a mid-season raise lost because…", a: ["They were already bound to do that work", "The raise was oral", "They had joined a union"], c: 0, x: "Ninth Circuit, 1902: the pre-existing duty rule. A promise to pay more for the same work lacks consideration." },
    { q: "Stilk v Myrick (1809) held sailors could not claim extra pay promised after two crewmen…", a: ["Deserted mid-voyage", "Died of fever", "Were promoted"], c: 0, x: "The remaining crew were already bound to sail the ship home, so the promise to share the deserters' wages lacked consideration." },
    { q: "In Williams v Roffey Bros, a carpenter could enforce a promise of extra pay because the builder received…", a: ["A practical benefit", "A formal release", "A signed deed"], c: 0, x: "Court of Appeal, 1989: avoiding a late-completion penalty and the hassle of replacing him was enough, softening Stilk v Myrick." },
    { q: "Foakes v Beer (1884) held that a creditor's promise to accept part payment of a debt in full satisfaction is…", a: ["Unenforceable for lack of consideration", "Binding once paid", "Binding if made orally"], c: 0, x: "The House of Lords applied Pinnel's Case (1602): Mrs Beer could still claim interest on the judgment debt Dr Foakes had paid off." },
    { q: "In the High Trees case, Denning J held a landlord bound by a promise to halve the ground rent during…", a: ["The Second World War", "A building strike", "The Great Depression"], c: 0, x: "Flats stood empty in wartime London. The promise bound while those conditions lasted, the birth of English promissory estoppel." },
    { q: "Taylor v Caldwell (1863), the foundation of impossibility doctrine, arose when what burned down?", a: ["A music hall", "A cotton mill", "A grain warehouse"], c: 0, x: "The Surrey Gardens Music Hall was destroyed before the concerts. Blackburn J implied a condition that the venue would continue to exist." },
    { q: "Krell v Henry (1903) excused the hirer of a Pall Mall flat because the event he hired it to watch was…", a: ["Edward VII's postponed coronation procession", "The Boat Race", "A royal wedding"], c: 0, x: "The coronation was postponed when the King fell ill. The contract's foundation was gone, a leading frustration-of-purpose case." },
    { q: "In Herne Bay Steam Boat Co v Hutton (1903), hire of a boat to view a naval review was NOT frustrated by its cancellation because…", a: ["Cruising round the fleet was still possible", "The boat was still seaworthy", "The hirer had prepaid"], c: 0, x: "A coronation-era companion to Krell v Henry: the review was not the sole foundation of the contract, as the fleet remained at Spithead." },
    { q: "Paradine v Jane (1647) held a tenant liable for rent though he had been driven off the land by…", a: ["Prince Rupert's army", "A plague outbreak", "A river flood"], c: 0, x: "The old rule of absolute contracts: a party who wants an excuse for supervening events must provide for it in the contract." },
    { q: "In Davis Contractors v Fareham UDC (1956), a builder hit by labour shortages and long delays found the contract was…", a: ["Not frustrated", "Frustrated", "Void for mistake"], c: 0, x: "House of Lords: frustration needs performance to be radically different, not merely more onerous or expensive than expected." },
    { q: "After the 1956 Suez Canal closure, the House of Lords in Tsakiroglou v Noblee Thorl held a cargo contract was…", a: ["Not frustrated: ship via the Cape", "Frustrated automatically", "Suspended until reopening"], c: 0, x: "Shipping groundnuts around the Cape of Good Hope was longer and costlier, but not fundamentally different performance." },
    { q: "Transatlantic Financing Corp. v. United States (1966) rejected impracticability after the Suez closure lengthened a voyage carrying…", a: ["Wheat to Iran", "Oil to Britain", "Troops to Korea"], c: 0, x: "D.C. Circuit: the extra cost of sailing around the Cape was not enough. The carrier had assumed that risk." },
    { q: "In Mitchill v. Lath, the buyer of a farm tried to prove the seller's oral promise to remove…", a: ["An ice house", "A dilapidated barn", "A billboard"], c: 0, x: "New York, 1928: the promise was one parties would ordinarily include in the written deal, so the parol evidence rule kept it out." },
    { q: "Pacific Gas & Electric v. Thomas Drayage (1968) let courts hear extrinsic evidence to show that a writing…", a: ["Is reasonably susceptible to another meaning", "Was forged", "Was never signed"], c: 0, x: "Justice Traynor rejected plain-meaning purism: words have no meaning apart from context. The dispute was over an indemnity clause." },
    { q: "Judge Friendly's opinion in Frigaliment v. B.N.S. International Sales famously opens with the question…", a: ["What is chicken?", "What is a pound?", "What is a sale?"], c: 0, x: "S.D.N.Y., 1960: the buyer wanted young broilers; the seller shipped stewing fowl. The buyer failed to prove the narrower meaning." },
    { q: "ProCD v. Zeidenberg (1996) held enforceable a software license that was…", a: ["Inside the box and accepted by use", "Printed only on the receipt", "Never shown to the buyer"], c: 0, x: "Judge Easterbrook (7th Cir.): terms inside the box bind if the buyer can read them and return the product, but keeps it instead." },
    { q: "In Hill v. Gateway 2000, buyers of a computer were bound by an arbitration clause in the box because they…", a: ["Kept it beyond the 30-day return window", "Signed at the store", "Clicked 'I agree' online"], c: 0, x: "Seventh Circuit, 1997: 'accept-or-return' terms shipped with the product became binding when the buyers kept the PC past 30 days." },
    { q: "In Dickinson v Dodds (1876), an offer was held to be revoked when the offeree learned of a sale to someone else…", a: ["From a reliable third party", "From the land registry", "Only from the offeror in writing"], c: 0, x: "Court of Appeal: once Dickinson knew from Berry that Dodds had sold to Allan, there was no longer an offer capable of acceptance." },
    { q: "Hyde v Wrench (1840) established that a counter-offer…", a: ["Destroys the original offer", "Extends the offer's deadline", "Is a binding acceptance"], c: 0, x: "Wrench offered his farm for £1,000; Hyde offered £950. Once refused, Hyde's later attempt to accept £1,000 came too late." },
    { q: "In Felthouse v Bindley (1862), an uncle wrote 'If I hear no more about him, I consider the horse mine.' The court held…", a: ["Silence was not acceptance", "The horse was sold", "The nephew was estopped"], c: 0, x: "An offeror cannot impose a contract by declaring that the other side's silence will count as acceptance." },
    { q: "Entores v Miles Far East (1955) held that an acceptance sent by telex takes effect…", a: ["Where and when it is received", "When it is typed", "When the offeror replies"], c: 0, x: "Instantaneous communications get the receipt rule, not the postal rule. That decided where the contract was made." },
    { q: "Fisher v Bell held that a flick knife displayed in a shop window was…", a: ["An invitation to treat, not an offer", "An offer for sale", "Abandoned property"], c: 0, x: "A shopkeeper was acquitted of 'offering for sale' a flick knife because, in contract law, a window display only invites offers." },
    { q: "In Pharmaceutical Society v Boots (1953), the contract in a self-service shop was formed…", a: ["At the cash desk", "When goods went in the basket", "At the shop door"], c: 0, x: "Shelf displays are invitations to treat. The customer makes the offer at the till, where a pharmacist could supervise the sale." },
    { q: "Partridge v Crittenden (1968) held that a magazine ad offering bramblefinches for sale was…", a: ["An invitation to treat", "A unilateral offer", "A binding auction"], c: 0, x: "Ads for goods are generally invitations to treat; otherwise the seller could be bound to more buyers than it has birds." },
    { q: "Balfour v Balfour (1919) held a husband's promise of a monthly allowance unenforceable because…", a: ["There was no intention to create legal relations", "The sum was uncertain", "It was not witnessed"], c: 0, x: "Domestic arrangements between spouses living together are presumed not to be intended as legally binding." },
    { q: "In Merritt v Merritt (1970), a husband's signed promise to his wife was enforceable, unlike in Balfour, because the couple…", a: ["Had already separated", "Had married abroad", "Had used a solicitor"], c: 0, x: "Once spouses have separated, the presumption against intending legal relations falls away." },
    { q: "Chappell & Co v Nestlé held that chocolate bar wrappers sent in to obtain a record were…", a: ["Part of the consideration", "Worthless and irrelevant", "A conditional gift"], c: 0, x: "House of Lords: Nestlé threw the wrappers away, but they were part of what it bargained for, which mattered for copyright royalties." },
    { q: "The Moorcock (1889) is the classic authority for implying a term to give a contract…", a: ["Business efficacy", "Moral fairness", "Statutory compliance"], c: 0, x: "A ship grounded at a Thames jetty. The court implied a promise that the berth was reasonably safe, as the deal needed it to work." },
    { q: "The 'officious bystander' test asks whether, if a bystander suggested a term, the parties would…", a: ["Testily say 'Oh, of course!'", "Agree to negotiate it", "Ask their lawyers"], c: 0, x: "From Shirlaw v Southern Foundries (1939), per MacKinnon LJ: terms so obvious they go without saying may be implied." },
    { q: "L'Estrange v Graucob (1934) stands for the rule that a person who signs a contract is bound even if…", a: ["They never read it", "The other side lied about it", "They signed as a minor"], c: 0, x: "Miss L'Estrange signed small print excluding warranties on a cigarette vending machine. Absent fraud or misrepresentation, the signature bound her." },
    { q: "In Curtis v Chemical Cleaning (1951), a customer escaped a signed exclusion clause because the shop assistant…", a: ["Misrepresented its scope", "Forgot to sign it", "Had no authority"], c: 0, x: "She was told it only covered beads and sequins on her wedding dress. Misrepresenting an exemption clause defeats reliance on it." },
    { q: "Olley v Marlborough Court Hotel held an exclusion notice in a hotel bedroom ineffective because…", a: ["The contract was made at reception first", "It was handwritten", "The guest was a minor"], c: 0, x: "Terms must be brought to notice before or at formation. Mrs Olley's furs were stolen, and the bedroom notice came too late." },
    { q: "Lord Denning said some onerous clauses would need to be printed in red ink with…", a: ["A red hand pointing to them", "A gold seal", "The judge's signature"], c: 0, x: "The 'red hand rule' from Spurling v Bradshaw (1956): the more unusual or onerous a term, the more notice is needed to incorporate it." },
    { q: "Interfoto v Stiletto refused to enforce a steep holding fee for the late return of…", a: ["Photographic transparencies", "Rental cars", "Library books"], c: 0, x: "Court of Appeal: an unusually onerous term buried in a delivery note must be fairly brought to the other party's attention." },
    { q: "In Photo Production v Securicor (1980), an exclusion clause protected a security firm even though its patrolman…", a: ["Started a fire that burned the factory", "Fell asleep on duty", "Lost the keys"], c: 0, x: "The House of Lords ended the 'fundamental breach' rule of law: whether an exclusion covers a breach is a matter of construction." },
    { q: "Hong Kong Fir Shipping introduced 'innominate' terms, whose breach permits termination only if it…", a: ["Deprives the innocent party of substantially the whole benefit", "Occurs in the first week", "Is admitted in writing"], c: 0, x: "A chartered ship's incompetent engine-room crew caused long delays, but not enough to end the charter. Consequences, not labels, decided." },
    { q: "Bettini v Gye (1876) held that a singer who arrived late, missing only rehearsals, had breached a…", a: ["Warranty, not a condition", "Condition, ending the contract", "Fiduciary duty"], c: 0, x: "Contrast Poussard v Spiers the same year, where a singer who missed opening nights broke a condition and could be replaced." },
    { q: "In Bell v Lever Brothers, large severance payments to executives were NOT recoverable for mistake, even though…", a: ["Their misconduct would have justified free dismissal", "The payments were tax-free", "They had already resigned"], c: 0, x: "House of Lords: the mistake was not fundamental enough. Common mistake about quality rarely makes a contract void." },
    { q: "Couturier v Hastie (1856) concerned a cargo of corn that, unknown to both parties, had already been…", a: ["Sold off after it fermented", "Insured twice", "Seized by pirates"], c: 0, x: "The goods had ceased to exist as a commercial thing when the contract was made, so the buyer was not liable to pay." },
    { q: "In Cundy v Lindsay (1878), a rogue named Blenkarn ordered goods using a signature made to look like…", a: ["Blenkiron & Co, a respectable firm", "The Bank of England", "A royal warrant holder"], c: 0, x: "Lindsay meant to deal only with Blenkiron, so no contract arose with the rogue and the innocent buyer of the goods got no title." },
    { q: "Derry v Peek (1889) defined fraud; the prospectus at issue claimed a tramway company could use…", a: ["Steam power", "Electric power", "Underground tunnels"], c: 0, x: "The directors honestly believed Board of Trade consent was a formality. Honest belief, however careless, is not fraud." },
    { q: "Smith v Hughes (1871) involved a buyer who thought he was getting old oats but was sold…", a: ["New, green oats", "Barley", "Spoiled oats"], c: 0, x: "The seller had no duty to correct the buyer's silent mistake about quality. Agreement is judged objectively." },
    { q: "Addis v Gramophone Co (1909) held that damages for wrongful dismissal do not cover…", a: ["Injured feelings from the manner of dismissal", "Salary for the notice period", "Commission already earned"], c: 0, x: "The House of Lords confined contract damages to financial loss, the root of the general rule against mental distress awards." },
    { q: "Jarvis v Swans Tours awarded damages for disappointment after a holiday failed to deliver promised…", a: ["Swiss house-party fun", "Caribbean sunshine", "A cruise upgrade"], c: 0, x: "Lord Denning held that where a contract promises enjoyment, damages can compensate for lost enjoyment, an exception to Addis." },
    { q: "In Ruxley Electronics v Forsyth, a swimming pool built shallower than agreed earned the owner…", a: ["£2,500 for loss of amenity", "The full cost of rebuilding it", "Nothing at all"], c: 0, x: "The House of Lords refused unreasonable reinstatement costs where the pool's value was unaffected, but upheld a modest amenity award." },
    { q: "In Victoria Laundry v Newman (1949), a late boiler let the laundry recover ordinary lost profits but not profits from…", a: ["Unusually lucrative dyeing contracts", "Staff overtime", "Any source at all"], c: 0, x: "The seller knew a laundry needed a boiler, but not about the special government contracts. Remoteness turns on what was known." },
    { q: "In Koufos v Czarnikow (The Heron II), a ship's delay caused loss because the market price of its cargo had fallen. The cargo was…", a: ["Sugar", "Coal", "Wool"], c: 0, x: "House of Lords: contract remoteness requires loss to be 'not unlikely', a stricter test than reasonable foreseeability in tort." },
    { q: "Robinson v Harman (1848) says contract damages aim to put the claimant, so far as money can, in the position…", a: ["As if the contract had been performed", "As before the contract was made", "Of the defendant"], c: 0, x: "The classic statement of the expectation measure in English law." },
    { q: "In Anglia Television v Reed, an actor who pulled out of a TV film was liable for…", a: ["Wasted expenses, even pre-contract ones", "The film's projected profits", "Nothing, as profits were speculative"], c: 0, x: "Where profits are too speculative, a claimant may claim reliance damages instead, including spending before the contract was signed." },
    { q: "Cavendish v Makdessi (2015) replaced the 'genuine pre-estimate' test for penalties with whether a clause…", a: ["Protects a legitimate interest proportionately", "Benefits the weaker party", "Was drafted by lawyers"], c: 0, x: "UK Supreme Court. In the companion case, ParkingEye v Beavis, an £85 overstay charge survived the new test." },
    { q: "Dunlop v Selfridge (1915) is a leading English case on…", a: ["Privity of contract", "Frustration", "Duress"], c: 0, x: "Dunlop could not enforce a resale price agreement between a dealer and Selfridge: it was not a party and gave no consideration." },
    { q: "In Tweddle v Atkinson (1861), a groom couldn't enforce a promise between his father and father-in-law to pay him because…", a: ["He was not a party to the contract", "The wedding was cancelled", "The promise was oral"], c: 0, x: "Classic privity: consideration must move from the promisee. English statute reformed the rule in 1999." },
    { q: "The Contracts (Rights of Third Parties) Act 1999 lets a non-party enforce a term if…", a: ["The term purports to confer a benefit on them", "They pay a fee", "A court approves first"], c: 0, x: "That is why so many English-law contracts include a 'no third-party rights' boilerplate clause excluding the Act." },
    { q: "Lawrence v. Fox (1859) is the landmark New York case allowing…", a: ["A third-party beneficiary to sue", "Oral land sales", "Minors to void contracts"], c: 0, x: "Fox promised Holly to pay Holly's $300 debt to Lawrence. Lawrence, a stranger to the deal, could enforce the promise." },
    { q: "Shuey v. United States (1875) held that a reward offer for a Lincoln assassination conspirator could be revoked by…", a: ["Equal publicity to the original offer", "Personal notice to every reader", "Only a court order"], c: 0, x: "The War Department's reward for John Surratt had been publicly withdrawn. A general offer can be revoked the way it was made." },
    { q: "Kirksey v. Kirksey (1845) held unenforceable a brother-in-law's promise of a place to live because it was…", a: ["A gratuitous promise, not a bargain", "Made by letter", "Too vague"], c: 0, x: "The widow moved some 60 miles relying on it, yet Alabama saw only a conditional gift. Promissory estoppel later revisited such cases." },
    { q: "In Allegheny College v. National Chautauqua County Bank (1927), Cardozo found consideration for a pledge in the college's implied duty to…", a: ["Perpetuate the donor's name", "Build a new chapel", "Admit her children"], c: 0, x: "The $5,000 pledge was for a memorial fund in the donor's name. Accepting part of it implied a promise to honour that condition." },
    { q: "Cotnam v. Wisdom (1907) let a surgeon recover fees for treating an unconscious accident victim on the basis of…", a: ["An implied-in-law (quasi) contract", "An express oral contract", "Promissory estoppel"], c: 0, x: "The patient never agreed and died without regaining consciousness, but the law implies a promise to prevent unjust enrichment." },
    { q: "Britton v. Turner (1834) let a farmhand who quit before his one-year term ended recover…", a: ["The reasonable value of his work", "His full year's wages", "Nothing at all"], c: 0, x: "New Hampshire rejected the harsh rule that a breaching worker forfeits everything, allowing restitution less the employer's damages." },
    { q: "In Parker v. Twentieth Century-Fox (1970), an actress needn't mitigate by accepting a substitute role in a…", a: ["Western to be filmed in Australia", "Sequel to her own film", "Broadway play"], c: 0, x: "California: the substitute ('Big Country, Big Man') was different and inferior to the musical 'Bloomer Girl', so refusing it was reasonable." },
    { q: "In Rockingham County v. Luten Bridge Co. (1929), the builder couldn't recover for work after the county cancelled because it…", a: ["Should have stopped and mitigated", "Lacked a permit", "Used poor materials"], c: 0, x: "Fourth Circuit: after a repudiation, you cannot pile up damages by building a bridge to nowhere." },
    { q: "Hochster v De la Tour (1853) let a courier sue before his tour was due to start, establishing…", a: ["Anticipatory repudiation", "The postal rule", "Quantum meruit"], c: 0, x: "The employer cancelled in advance, and the courier didn't have to wait until the start date to bring his claim." },
    { q: "Lord Mansfield's decision in Kingston v. Preston (1773) is famous for developing…", a: ["Dependent promises (constructive conditions)", "The postal rule", "Liquidated damages"], c: 0, x: "An apprentice couldn't force a sale of the silk business without first giving the security he had promised. Performances can be mutually conditional." },
    { q: "Sullivan v. O'Connor (1973), a breach of promise case about cosmetic surgery, concerned a patient's…", a: ["Nose", "Hairline", "Teeth"], c: 0, x: "Massachusetts allowed reliance damages, including pain and suffering from extra operations, rather than full expectation damages." },
    { q: "Laidlaw v. Organ (1817) involved a buyer of tobacco who knew, before the seller did, that…", a: ["The War of 1812 had ended", "A fire had destroyed a rival crop", "Tariffs were rising"], c: 0, x: "Chief Justice Marshall: absent a duty or active deception, a buyer need not share superior market news, here of the Treaty of Ghent." },
    { q: "Vokes v. Arthur Murray, Inc. (1968) let a widow escape contracts for more than 2,300 hours of…", a: ["Dance lessons", "Piano lessons", "Golf lessons"], c: 0, x: "Florida: flattery about her 'dancing potential' from a party with superior knowledge could amount to actionable misrepresentation." },
    { q: "Bloor v. Falstaff Brewing (1979) found a breach of a 'best efforts' clause covering which beer brand?", a: ["Ballantine", "Schlitz", "Pabst"], c: 0, x: "Falstaff bought the Ballantine brand and let its sales collapse while chasing profit. Best efforts meant more than favouring its own bottom line." },
    { q: "In Lefkowitz v. Great Minneapolis Surplus Store (1957), an ad offering a fur stole for $1, 'first come, first served', was…", a: ["A binding offer", "Mere puffery", "An invitation to treat"], c: 0, x: "The ad was clear and definite and left nothing open. The store's later 'house rule' limiting it to women came too late." },
    { q: "Lumley v Wagner (1852) let a theatre manager stop an opera singer from…", a: ["Singing at a rival theatre", "Leaving England", "Recording her songs"], c: 0, x: "Courts won't order personal services, but they can enforce a negative promise not to perform elsewhere: the negative injunction." },
    { q: "Lumley v Gye (1853), arising from the same opera-singer dispute, recognised the tort of…", a: ["Inducing breach of contract", "Negligent misstatement", "Passing off"], c: 0, x: "Frederick Gye of Covent Garden lured Johanna Wagner away. Knowingly procuring a breach became actionable against the outsider." },
    { q: "Pennzoil v. Texaco produced a record Texas jury verdict of about $10.5 billion over the acquisition of…", a: ["Getty Oil", "Gulf Oil", "Mobil"], c: 0, x: "The jury found Pennzoil had a binding deal with Getty that Texaco induced it to breach. Texaco eventually settled for $3 billion." },
    { q: "Rose and Frank Co v JR Crompton held a distribution arrangement not legally binding because it described itself as…", a: ["An honourable pledge only", "Subject to board approval", "Written in pencil"], c: 0, x: "Express words excluding legal relations are respected, though individual orders actually placed and accepted were binding." },
    { q: "In Gibson v Manchester City Council (1979), a letter saying the council 'may be prepared to sell' a house was…", a: ["Not an offer", "A binding offer", "An acceptance"], c: 0, x: "House of Lords: tentative willingness is an invitation to treat. Political control changed and council-house sales were halted." },
    { q: "In Harvey v Facey (1893), a telegram stating 'Lowest price for Bumper Hall Pen £900' was held to be…", a: ["Information, not an offer", "A binding offer", "A counter-offer"], c: 0, x: "Privy Council, on appeal from Jamaica: answering a question about price is not an offer to sell at that price." },
    { q: "Butler Machine Tool v Ex-Cell-O, an English battle-of-the-forms case, was won by the party whose terms…", a: ["Were on a tear-off slip the other side signed and returned", "Were sent first", "Were longest"], c: 0, x: "The seller returned the buyer's acknowledgment slip, accepting the buyer's counter-offer and losing its price-variation clause." },
    { q: "In R v Clarke (1927), an Australian who supplied information covered by a reward offer lost his claim because he…", a: ["Wasn't acting in response to the offer", "Was a police officer", "Missed the deadline"], c: 0, x: "High Court of Australia: he had forgotten the reward and acted to clear himself, so there was no acceptance of the offer." },
    { q: "Shanklin Pier v Detel Products (1951) let a pier owner sue a paint maker it never bought from, via…", a: ["A collateral contract", "Promissory estoppel", "A bailment"], c: 0, x: "The paint maker promised the paint would last seven years; in return, the pier owner had its contractors buy that paint." },
    { q: "In Oscar Chess v Williams (1957), a private seller's mistaken statement about a car's age was held to be…", a: ["A mere representation, not a term", "A condition", "A fraudulent warranty"], c: 0, x: "Contrast Dick Bentley v Harold Smith (1965), where a dealer's mileage statement was a term. Expertise matters." },
    { q: "In Schuler v Wickman, a clause calling weekly sales visits a 'condition' didn't let one missed visit end the deal because…", a: ["That result would be unreasonable", "The clause was oral", "Visits can't be contract terms"], c: 0, x: "House of Lords: labels matter, but 'condition' was read in a less drastic sense where the literal effect was absurd." },
    { q: "In Arnold v Britton (2015), the UK Supreme Court enforced a service charge rising 10% a year compounded because…", a: ["The words were clear, however bad the bargain", "The tenants agreed later", "Inflation was high"], c: 0, x: "Courts won't rewrite clear language to rescue a party from a deal that looks bad with hindsight. Commercial common sense has limits." },
    { q: "Rainy Sky v Kookmin Bank (2011) said that where a clause has two possible meanings, a court should prefer the one…", a: ["Most consistent with business common sense", "Favouring the bank", "Drafted most recently"], c: 0, x: "UK Supreme Court, in a dispute over shipbuilding refund guarantees. Arnold v Britton later tempered the approach." },
    { q: "Lord Hoffmann's five principles of contractual interpretation were set out in…", a: ["ICS v West Bromwich Building Society", "Donoghue v Stevenson (1932)", "Salomon v Salomon (1897)"], c: 0, x: "Meaning is what the document would convey to a reasonable person with all the background knowledge reasonably available to the parties." },
    { q: "Chartbrook v Persimmon Homes (2009) reaffirmed that, in English law, evidence of pre-contractual negotiations is generally…", a: ["Inadmissible to interpret the contract", "Decisive", "Admissible only for consumers"], c: 0, x: "The House of Lords kept the exclusionary rule, but corrected an obvious drafting mistake through construction instead." },
    { q: "White and Carter v McGregor let an advertising firm ignore a client's repudiation and claim the full price for ads on…", a: ["Litter bins", "Buses", "Billboards"], c: 0, x: "House of Lords: an innocent party may affirm and perform if it needs no cooperation, unless it has no legitimate interest in doing so." },
    { q: "In The Super Servant Two, a carrier couldn't claim frustration after one of its vessels sank because…", a: ["It chose to use its other vessel elsewhere", "It was uninsured", "The vessel sank in port"], c: 0, x: "Allocating Super Servant One to other contracts was the carrier's own choice, so any frustration was self-induced." },
    { q: "In Canary Wharf v European Medicines Agency (2019), the High Court held that Brexit…", a: ["Did not frustrate the agency's London lease", "Frustrated every EU-related contract", "Voided the lease for mistake"], c: 0, x: "The EMA remained bound by its 25-year lease: paying rent and using or disposing of the premises was still possible." },
    { q: "The Law Reform (Frustrated Contracts) Act 1943 allows an English court, after frustration, to…", a: ["Order repayment of money paid in advance", "Revive the contract", "Award punitive damages"], c: 0, x: "Passed after the Fibrosa case. The court may let the payee keep a sum to cover expenses it has incurred." },
    { q: "Mattei v. Hopper (1958) held that a land purchase 'subject to' the buyer being satisfied with the leases obtained was…", a: ["Not illusory, as good faith limited it", "Illusory and void", "A gift"], c: 0, x: "California: satisfaction clauses are bounded by good faith, so the buyer's promise was real consideration." },
    { q: "Joseph Martin, Jr., Delicatessen v. Schumacher (1981) held a lease renewal at a rent 'to be agreed upon' was…", a: ["Unenforceable as an agreement to agree", "Enforceable at market rent", "A fixed-rent option"], c: 0, x: "New York's Court of Appeals refused to supply the missing rent. Without a method or standard, there was nothing to enforce." },
    { q: "In Chicago Coliseum Club v. Dempsey (1932), a promoter couldn't recover expected profits from a prize fight because they were…", a: ["Too speculative", "From illegal gambling", "Paid in advance"], c: 0, x: "Jack Dempsey refused to fight Harry Wills. The court allowed only certain expenses incurred after the contract was signed." },
    { q: "In Globe Refining v. Landa Cotton Oil (1903), Justice Holmes said liability for consequential loss requires…", a: ["A tacit agreement to bear the risk", "Proof of malice", "A written warranty"], c: 0, x: "The UCC's official comments reject Holmes' 'tacit agreement' test; § 2-715 asks only whether the seller had reason to know." },
    { q: "Nanakuli Paving v. Shell Oil (1981) let Hawaiian trade usage supplement an express price term, requiring Shell to give…", a: ["Price protection on asphalt", "Free delivery of gasoline", "Exclusive dealer rights"], c: 0, x: "Ninth Circuit: under the UCC, usage of trade and course of performance can supplement, even seemingly qualify, express terms." },
    { q: "In Lenawee County Board of Health v. Messerly (1982), a buyer of property with a defective septic system lost because of…", a: ["An 'as is' clause allocating the risk", "Lack of a written contract", "The buyer's own fraud"], c: 0, x: "Michigan cut back Sherwood v. Walker: where the contract allocates the risk, mutual mistake won't rescue the buyer." },
    { q: "Crabtree v. Elizabeth Arden Sales Corp. (1953) satisfied the Statute of Frauds by piecing together…", a: ["Signed and unsigned payroll records", "Telegrams from abroad", "A recorded phone call"], c: 0, x: "New York allowed unsigned writings to be read with signed ones where they clearly refer to the same transaction." },
    { q: "Attorney General v Blake, decided by the House of Lords in 2000, ordered a former spy to account for profits from his…", a: ["Autobiography", "Pension", "Property sales"], c: 0, x: "Disgorgement of profits for breach of contract is available in 'exceptional' cases where ordinary damages are inadequate." },
    { q: "Fuller and Perdue's famous 1936 article named three contract interests: expectation, reliance and…", a: ["Restitution", "Retribution", "Reputation"], c: 0, x: "'The Reliance Interest in Contract Damages', published in the Yale Law Journal, remains one of the most cited law review articles." },
    { q: "In Beswick v Beswick, a widow obtained specific performance of her late husband's contract with his nephew in her capacity as…", a: ["Administratrix of his estate", "Third-party beneficiary", "Guarantor"], c: 0, x: "Privity barred her personal claim, but as administratrix she could compel the nephew to pay the promised annuity." },
    { q: "Co-operative Insurance v Argyll Stores refused to order a supermarket to…", a: ["Keep trading under a keep-open covenant", "Pay its rent", "Leave the premises"], c: 0, x: "The House of Lords would not compel a loss-making business to keep running, which would need constant court supervision." },
    { q: "Nordenfelt v Maxim Nordenfelt (1894) upheld a worldwide non-compete given by the seller of an…", a: ["Arms and ammunition business", "Ocean shipping line", "Tea plantation"], c: 0, x: "Restraints of trade are void unless reasonable. Selling a business's goodwill can justify wider restraints than employment." },
    { q: "Mitchel v Reynolds (1711), the foundational restraint-of-trade case, concerned a…", a: ["Bakery", "Blacksmith's forge", "Printing press"], c: 0, x: "A partial, reasonable restraint supported by consideration was upheld, the start of the reasonableness test for non-competes." },
    { q: "The FTC's 2024 rule banning most worker non-compete agreements…", a: ["Was set aside by a federal court before taking effect", "Took effect nationwide in 2024", "Applied only to doctors"], c: 0, x: "A Texas federal court vacated the rule in August 2024. Non-competes remain governed largely by state law." },
    { q: "Which state generally voids employee non-compete agreements under Business and Professions Code § 16600?", a: ["California", "Texas", "Florida"], c: 0, x: "California's ban is long-standing. Edwards v. Arthur Andersen (2008) rejected a 'narrow restraint' exception." },
    { q: "UCC Article 2 governs contracts for the sale of…", a: ["Goods", "Real estate", "Services"], c: 0, x: "Goods are things movable at the time of identification. Mixed goods-and-services deals usually turn on a 'predominant purpose' test." },
    { q: "Under UCC § 2-201, a contract for the sale of goods generally needs a signed writing if the price is at least…", a: ["$500", "$5,000", "$50"], c: 0, x: "A 2003 amendment proposed $5,000, but those amendments were withdrawn in 2011 without being adopted. $500 remains the rule." },
    { q: "Between merchants, a written confirmation satisfies the UCC Statute of Frauds against the recipient unless they object within…", a: ["10 days", "30 days", "48 hours"], c: 0, x: "UCC § 2-201(2): failing to object to a confirmation you have reason to know about can bind you." },
    { q: "A merchant's signed 'firm offer' under UCC § 2-205 can stay irrevocable without consideration for up to…", a: ["Three months", "One year", "Ten days"], c: 0, x: "Unlike the common law, the UCC lets merchants make binding firm offers, but the assurance must be in a signed record." },
    { q: "The UCC 'perfect tender' rule lets a buyer reject goods that…", a: ["Fail to conform in any respect", "Are materially defective only", "Arrive after payment"], c: 0, x: "Section 2-601 is softened by the seller's right to cure (§ 2-508) and special rules for installment contracts." },
    { q: "The UCC implied warranty of merchantability arises automatically when the seller is…", a: ["A merchant in goods of that kind", "A bank", "Any private seller"], c: 0, x: "Under § 2-314, goods must be fit for their ordinary purpose. A written disclaimer must mention merchantability and be conspicuous." },
    { q: "The UCC implied warranty of fitness for a particular purpose requires that the buyer…", a: ["Relied on the seller's skill to select the goods", "Paid in cash", "Inspected the goods first"], c: 0, x: "Under § 2-315, the seller must have reason to know the buyer's purpose and reliance. It can apply to non-merchant sellers too." },
    { q: "Under UCC § 2-316, which phrase typically excludes all implied warranties?", a: ["'As is'", "'Best efforts'", "'Time is of the essence'"], c: 0, x: "'As is', 'with all faults' and similar language make plain to the buyer that there is no implied warranty." },
    { q: "When a seller fails to deliver, a buyer who 'covers' under the UCC…", a: ["Buys substitutes and claims the price difference", "Sues for the full purchase price", "Insures the shipment"], c: 0, x: "UCC § 2-712: the buyer recovers cover price minus contract price, plus incidental and consequential damages, less expenses saved." },
    { q: "A 'lost volume seller' can recover its lost profit even after reselling the goods because…", a: ["It could have made both sales", "Resale prices always fall", "The buyer must pay twice"], c: 0, x: "A dealer with ample supply loses a sale when a buyer breaches. Reselling that item doesn't replace the lost deal (UCC § 2-708(2))." },
    { q: "Requirements and output contracts are saved from indefiniteness under UCC § 2-306 by requiring…", a: ["Good-faith quantities", "A fixed minimum", "Annual renegotiation"], c: 0, x: "No quantity may be unreasonably disproportionate to any stated estimate or, absent one, to normal prior requirements or output." },
    { q: "If a contract for goods is silent on price but the parties intended to be bound, UCC § 2-305 supplies…", a: ["A reasonable price at the time of delivery", "The seller's list price", "Nothing: the deal is void"], c: 0, x: "Open price terms don't defeat a contract for goods. The UCC fills gaps the common law might have treated as fatal." },
    { q: "Under an 'FOB shipping point' term, risk of loss usually passes to the buyer when…", a: ["The goods are delivered to the carrier", "The goods arrive", "The invoice is paid"], c: 0, x: "Under FOB destination, by contrast, the seller bears the risk until the goods are tendered at the destination." },
    { q: "The UCC statute of limitations for breach of a contract for the sale of goods is…", a: ["Four years", "Six years", "Two years"], c: 0, x: "Section 2-725 runs from breach. Parties may shorten it to not less than one year, but may not extend it." },
    { q: "UCC § 1-304 imposes on every contract or duty within the Code an obligation of…", a: ["Good faith in performance and enforcement", "Equal bargaining power", "Annual review"], c: 0, x: "Good faith under the UCC means honesty in fact and observance of reasonable commercial standards of fair dealing." },
    { q: "Under UCC § 1-303, which prevails if they conflict: express terms or usage of trade?", a: ["Express terms", "Usage of trade", "Whichever is more recent"], c: 0, x: "The hierarchy runs: express terms, then course of performance, then course of dealing, then usage of trade." },
    { q: "The Chief Reporter of the Uniform Commercial Code, its principal architect, was…", a: ["Karl Llewellyn", "Oliver Wendell Holmes Jr.", "Samuel Williston"], c: 0, x: "The legal realist led the project, with Soia Mentschikoff as Associate Chief Reporter." },
    { q: "The first state to enact the Uniform Commercial Code was…", a: ["Pennsylvania", "New York", "California"], c: 0, x: "Pennsylvania adopted it in 1953. New York held out until 1962, after a long study by its Law Revision Commission." },
    { q: "Which US state has never adopted UCC Article 2?", a: ["Louisiana", "Texas", "Delaware"], c: 0, x: "Louisiana's civil-law tradition keeps its sales rules in its Civil Code, though it has adopted most other UCC articles." },
    { q: "Which major trading nation has NOT ratified the UN Convention on Contracts for the International Sale of Goods (CISG)?", a: ["The United Kingdom", "The United States", "China"], c: 0, x: "The CISG applies automatically between parties in contracting states, hence the common CISG exclusion in governing-law clauses." },
    { q: "The CISG is often called the Vienna Sales Convention because it was adopted in Vienna in…", a: ["1980", "1958", "2001"], c: 0, x: "It entered into force in 1988. The 1958 date belongs to the New York Convention on foreign arbitral awards." },
    { q: "Under CISG Article 11, a contract for the international sale of goods…", a: ["Need not be in writing", "Must be notarised", "Must be in English"], c: 0, x: "Unless a state has made a reservation, an international sale may be proved by any means, including witnesses." },
    { q: "The 1958 New York Convention matters to dispute resolution clauses because it governs…", a: ["Enforcement of foreign arbitral awards", "Choice-of-court agreements", "Sale of goods"], c: 0, x: "With more than 170 contracting states, it is why arbitral awards often travel across borders more easily than court judgments." },
    { q: "Incoterms, the trade terms such as FOB and CIF, are published by…", a: ["The International Chamber of Commerce", "The United Nations", "The World Trade Organization"], c: 0, x: "First issued in 1936 and revised periodically; Incoterms 2020 is the edition most contracts now reference." },
    { q: "In the trade term 'CIF', the letters stand for…", a: ["Cost, Insurance and Freight", "Carriage In Full", "Customs, Import, Freight"], c: 0, x: "The seller pays carriage and insurance to the named port, but risk passes to the buyer once the goods are on board." },
    { q: "The American Law Institute's Restatement (Second) of Contracts was published in…", a: ["1981", "1932", "2005"], c: 0, x: "The first Restatement of Contracts appeared in 1932, with Samuel Williston as Reporter." },
    { q: "Promissory estoppel is stated in which section of the Restatement of Contracts?", a: ["Section 90", "Section 2-207", "Section 1"], c: 0, x: "Section 90 enforces a promise the promisor should reasonably expect to induce reliance, if injustice can be avoided only by enforcement." },
    { q: "England's original Statute of Frauds was enacted in…", a: ["1677", "1215", "1832"], c: 0, x: "Passed in the reign of Charles II to curb perjury, it required written evidence for land sales, guarantees and other key contracts." },
    { q: "Which promise falls within the classic Statute of Frauds?", a: ["To answer for another's debt", "To sell a used bicycle for $20", "To paint a house next week"], c: 0, x: "The 'MY LEGS' mnemonic: Marriage, Year, Land, Executors, Goods of $500 or more, and Suretyship." },
    { q: "The 'main purpose' or 'leading object' rule takes an oral guarantee outside the Statute of Frauds when the guarantor…", a: ["Acts mainly for its own economic benefit", "Is a close relative", "Is a bank"], c: 0, x: "If you guarantee a supplier's debt chiefly to keep your own project running, the suretyship writing requirement may not apply." },
    { q: "In many US states, an oral contract for land can escape the Statute of Frauds through…", a: ["Part performance, such as possession and improvements", "A handshake before witnesses", "Payment in cash"], c: 0, x: "Taking possession and paying for or improving the property can point unmistakably to a contract, satisfying equity." },
    { q: "In England, s.2 of the Law of Property (Miscellaneous Provisions) Act 1989 requires a contract for the sale of land to be…", a: ["In writing with all terms, signed by both", "Witnessed by a notary", "Registered within a week"], c: 0, x: "It replaced s.40 of the Law of Property Act 1925, and with it the old doctrine of part performance for English land deals." },
    { q: "The US federal E-SIGN Act, giving electronic signatures and records legal effect, was enacted in…", a: ["2000", "1995", "2010"], c: 0, x: "With the state-level UETA, it means a contract can't be denied effect solely because it is in electronic form." },
    { q: "UETA, adopted by nearly every US state, stands for…", a: ["Uniform Electronic Transactions Act", "Universal E-Trade Agreement", "Unified Electronic Treaty Act"], c: 0, x: "Promulgated in 1999, it treats electronic records and signatures like paper ones where the parties agree to deal electronically." },
    { q: "Under the EU's eIDAS Regulation, which signature type has the equivalent legal effect of a handwritten signature?", a: ["Qualified electronic signature", "Simple electronic signature", "Scanned signature image"], c: 0, x: "eIDAS recognises simple, advanced and qualified e-signatures. Only the qualified type gets automatic handwritten equivalence." },
    { q: "Judge Learned Hand said a contract would bind even if twenty bishops testified a party meant otherwise. His point was…", a: ["The objective theory of contract", "The duty to read", "The rule against penalties"], c: 0, x: "From Hotchkiss v. National City Bank (1911): contracts arise from words and acts, not from the parties' private intentions." },
    { q: "If an offer states no deadline, it lapses…", a: ["After a reasonable time", "After exactly 30 days", "Never, until revoked"], c: 0, x: "What is reasonable depends on context: an offer to buy shares in a volatile market lapses far faster than an offer to sell land." },
    { q: "Under the traditional US rule, an ordinary offer terminates on the offeror's death…", a: ["Even if the offeree doesn't know of it", "Only after probate", "Only if publicly announced"], c: 0, x: "Restatement (Second) § 48 follows this much-criticised rule. Option contracts, by contrast, survive the offeror's death." },
    { q: "Under Restatement (Second) § 45, once an offeree begins the performance invited by a unilateral offer…", a: ["An option contract arises", "The offer lapses", "The offeree must finish or pay damages"], c: 0, x: "This answers the classic 'Brooklyn Bridge' puzzle: the offeror can't revoke when the walker is halfway across." },
    { q: "A promise to buy 'as many widgets as I may wish to order, if any' is classically…", a: ["Illusory, with no consideration", "A requirements contract", "A firm offer"], c: 0, x: "A promise leaving performance entirely to the promisor's whim binds nothing. Requirements contracts survive because they track real needs." },
    { q: "In Roscorla v Thomas (1842), a promise that a horse was 'sound and free from vice', made after the sale, failed because…", a: ["Past consideration is no consideration", "Horses aren't goods", "It wasn't in writing"], c: 0, x: "The sale was complete before the promise, so nothing new was given for it. The horse turned out to be vicious." },
    { q: "Lampleigh v Brathwait (1615) is the root of the exception to the past-consideration rule where the service was…", a: ["Performed at the promisor's request", "Worth under £1", "Done by a relative"], c: 0, x: "Brathwait asked Lampleigh to seek a royal pardon for him, then promised £100. The earlier request linked act and promise." },
    { q: "A contract made by a minor is generally voidable at the minor's option, but minors must pay a reasonable price for…", a: ["Necessaries", "Luxury goods", "Anything bought with cash"], c: 0, x: "Food, clothing, shelter and similar necessaries carry liability for their reasonable value, not necessarily the contract price." },
    { q: "Tunkl v. Regents of the University of California (1963) struck down a hospital admission form that…", a: ["Released the hospital from negligence liability", "Required binding arbitration", "Waived patient privacy"], c: 0, x: "California: exculpatory clauses affecting the public interest, such as essential services offered take-it-or-leave-it, are void." },
    { q: "Courts usually require two kinds of unconscionability before refusing to enforce a term. They are…", a: ["Procedural and substantive", "Express and implied", "Mutual and unilateral"], c: 0, x: "Procedural looks at the bargaining process (hidden terms, no real choice); substantive looks at harsh terms. Many courts use a sliding scale." },
    { q: "Which UCC section lets a court refuse to enforce an unconscionable contract or clause?", a: ["§ 2-302", "§ 2-314", "§ 2-725"], c: 0, x: "Unconscionability is decided by the court as a matter of law, judged as of the time the contract was made." },
    { q: "AT&T Mobility v. Concepcion (2011) held the Federal Arbitration Act preempts state rules that ban…", a: ["Class-action waivers in arbitration clauses", "All arbitration of consumer claims", "Choice-of-law clauses"], c: 0, x: "The Supreme Court struck down California's Discover Bank rule, cementing class waivers in consumer contracts." },
    { q: "The Federal Arbitration Act, which makes arbitration agreements 'valid, irrevocable, and enforceable', was enacted in…", a: ["1925", "1966", "1990"], c: 0, x: "It aimed to overcome judicial hostility to arbitration. Section 2 still preserves defenses such as fraud, duress and unconscionability." },
    { q: "The principal statute governing arbitrations seated in England is the…", a: ["Arbitration Act 1996", "Arbitration Act 1925", "Civil Procedure Act 1997"], c: 0, x: "It applies where the seat of arbitration is in England and Wales or Northern Ireland, which makes the seat a key drafting choice." },
    { q: "The Bremen v. Zapata Off-Shore Co. (1972) is the leading US Supreme Court case upholding…", a: ["Forum-selection clauses", "Arbitration of antitrust claims", "Liquidated damages"], c: 0, x: "A London-court clause in a contract to tow an oil rig was enforced: such clauses are prima facie valid unless unreasonable." },
    { q: "Carnival Cruise Lines v. Shute (1991) upheld a forum-selection clause printed on…", a: ["A cruise ticket", "A hotel key card", "A parking stub"], c: 0, x: "The Supreme Court enforced the clause choosing Florida courts even though passengers never negotiated it." },
    { q: "'Force majeure' is French for…", a: ["Superior force", "Major forecast", "Forced agreement"], c: 0, x: "These clauses excuse delay or non-performance caused by listed events beyond a party's control. Courts read the list closely." },
    { q: "Under English law, force majeure relief is available…", a: ["Only if the contract provides for it", "Automatically for any disaster", "Only for government action"], c: 0, x: "English law has no general force majeure doctrine. Without a clause, a party must rely on the narrow doctrine of frustration." },
    { q: "Under 'ejusdem generis', a general phrase such as 'or other causes' after a list of specific events is read as…", a: ["Limited to things of the same kind", "Covering absolutely anything", "Void for vagueness"], c: 0, x: "That's why force majeure clauses often add 'whether or not of the same kind as the foregoing' to keep catch-alls broad." },
    { q: "The 'contra proferentem' rule resolves ambiguity against…", a: ["The party who drafted or relies on the clause", "The smaller company", "The party who signed last"], c: 0, x: "Often neutralised by boilerplate saying the contract shall not be construed against either party as its drafter." },
    { q: "An 'entire agreement' clause is mainly designed to…", a: ["Exclude prior negotiations and side promises", "List every party's affiliates", "Fix the governing law"], c: 0, x: "In English law, it won't exclude misrepresentation claims on its own; a separate non-reliance clause is usually added." },
    { q: "A severability clause asks a court to…", a: ["Strike an invalid term and keep the rest", "Split the contract in two", "End ties with affiliates"], c: 0, x: "Without one, an illegal provision can sometimes taint the whole agreement." },
    { q: "The 'blue pencil' approach to an over-broad restrictive covenant lets a court…", a: ["Delete words, but not add or rewrite them", "Rewrite it to be reasonable", "Double its duration"], c: 0, x: "If striking words leaves a sensible, reasonable restraint, it survives. Some US states instead allow judicial reformation." },
    { q: "A 'counterparts' clause allows…", a: ["Each party to sign a separate copy", "Opposing counsel to draft", "Assignment to competitors"], c: 0, x: "All signed copies together form one instrument, which is handy when signatories are in different places." },
    { q: "Adding 'time is of the essence' to a contract means…", a: ["Missing a deadline is a material breach", "Deadlines are mere guidance", "Notice periods double"], c: 0, x: "Without it, courts often treat dates as non-essential, allowing performance within a reasonable time after the deadline." },
    { q: "A 'no waiver' clause is meant to ensure that…", a: ["Tolerating one breach doesn't forgive future ones", "No right can ever be waived", "Waivers must be paid for"], c: 0, x: "Courts sometimes still find waiver from conduct, such as a long pattern of accepting late payments without objection." },
    { q: "Under UCC § 9-406, a contract term prohibiting assignment of the right to receive payment is generally…", a: ["Ineffective", "Fully enforceable", "Enforceable only in writing"], c: 0, x: "Article 9 protects receivables financing, so anti-assignment clauses can't stop a creditor assigning its right to be paid." },
    { q: "A 'change of control' clause is typically triggered by…", a: ["A merger or acquisition of a party", "A change in the governing law", "A new CEO signing"], c: 0, x: "It lets the counterparty consent or terminate. It matters in M&A because a share sale doesn't otherwise assign the target's contracts." },
    { q: "A 'survival' clause specifies…", a: ["Which obligations continue after termination", "What happens if a party dies", "Emergency evacuation duties"], c: 0, x: "Confidentiality, indemnities, limitations of liability and accrued payment obligations are typical survivors." },
    { q: "Why do notice clauses specify addresses and methods such as courier or registered post?", a: ["So formal notices are provably effective", "To meet tax rules", "To satisfy the Statute of Frauds"], c: 0, x: "Courts often apply notice mechanics strictly. A termination sent the wrong way can be invalid." },
    { q: "An indemnity clause primarily…", a: ["Shifts specified losses from one party to another", "Sets the payment schedule", "Fixes the governing law"], c: 0, x: "Indemnities are often carved out of liability caps, which makes the cap and indemnity clauses the most negotiated pair in many deals." },
    { q: "Under the UK Unfair Contract Terms Act 1977, a business cannot exclude or restrict liability for…", a: ["Death or personal injury caused by negligence", "Lost profits", "Late delivery"], c: 0, x: "Section 2(1) makes such terms ineffective. Other negligence exclusions must satisfy the reasonableness test." },
    { q: "In the UK, unfair terms in consumer contracts are now mainly governed by the…", a: ["Consumer Rights Act 2015", "Sale of Goods Act 1893", "Misrepresentation Act 1967"], c: 0, x: "UCTA 1977 now focuses mainly on business-to-business contracts after the 2015 Act consolidated consumer protections." },
    { q: "The UK Sale of Goods Act 1979 implies that goods sold in the course of a business are of…", a: ["Satisfactory quality", "Merchantable quality", "Premium quality"], c: 0, x: "'Merchantable quality' was replaced by 'satisfactory quality' in 1994. Consumer sales now fall under the Consumer Rights Act 2015." },
    { q: "England's Sale of Goods Act 1893, a model for later US sales law, was drafted by…", a: ["Sir Mackenzie Chalmers", "Lord Denning", "Jeremy Bentham"], c: 0, x: "Chalmers also drafted the Bills of Exchange Act 1882. Williston's Uniform Sales Act (1906) drew heavily on his work." },
    { q: "Section 2(1) of the UK Misrepresentation Act 1967 makes a party liable for a negligent misrepresentation unless it proves…", a: ["Reasonable grounds to believe it was true", "It was not a lawyer", "The statement was oral"], c: 0, x: "This reverse burden, sometimes called the 'fiction of fraud', makes it a favourite claim over common-law negligent misstatement." },
    { q: "Akorn v. Fresenius (2018) was the first time a Delaware court let a buyer walk away from a merger because of…", a: ["A material adverse effect", "An antitrust rejection", "A financing failure"], c: 0, x: "Akorn's sudden business decline and data-integrity problems amounted to an MAE. The Delaware Supreme Court affirmed." },
    { q: "In IBP v. Tyson Foods (2001), the Delaware Court of Chancery ordered Tyson to complete its acquisition of…", a: ["Meatpacker IBP", "Fast-food chain KFC", "A grocery chain"], c: 0, x: "The court found no material adverse effect and granted specific performance, an unusual remedy for a merger agreement." },
    { q: "Under the 'knock-out rule' used by many US courts, conflicting terms in a buyer's and seller's forms…", a: ["Cancel out and are replaced by UCC gap-fillers", "Always favour the buyer", "Favour whoever sent the last form"], c: 0, x: "It is the majority reading of § 2-207 for 'different' terms. English law still tends to follow a 'last shot' analysis." },
    { q: "In an NDA, a 'residuals' clause permits the recipient to use…", a: ["Information retained in unaided memory", "Leftover marketing budgets", "Expired patents only"], c: 0, x: "Disclosers usually resist it, since it can swallow confidentiality for anything an engineer happens to remember." },
    { q: "A 'one-way' or unilateral NDA protects…", a: ["Only one party's disclosures", "Both parties equally", "Only public information"], c: 0, x: "Mutual NDAs suit deals where both sides share. One-way NDAs fit vendor evaluations or investor pitches." },
    { q: "Which is a standard exclusion from the definition of confidential information in an NDA?", a: ["Information independently developed by the recipient", "Information marked 'Secret'", "Source code"], c: 0, x: "Typical carve-outs: public information, prior knowledge, rightful receipt from a third party and independent development." },
    { q: "If a recipient is subpoenaed for the discloser's confidential information, a typical NDA requires it to…", a: ["Give prompt notice so the discloser can seek protection", "Destroy the information first", "Ignore the subpoena"], c: 0, x: "Compelled-disclosure clauses also usually limit disclosure to what counsel advises is legally required." },
    { q: "The US Defend Trade Secrets Act of 2016 conditions exemplary damages against an employee on the NDA including notice of…", a: ["Whistleblower immunity", "Arbitration rights", "Overtime rules"], c: 0, x: "Without the immunity notice, an employer cannot recover exemplary damages or attorney fees against an employee who wasn't notified." },
    { q: "Before the Defend Trade Secrets Act of 2016, US trade secret owners mainly sued under…", a: ["State law, usually based on the Uniform Trade Secrets Act", "The Lanham Act", "The Patent Act"], c: 0, x: "The DTSA created a federal civil claim, including ex parte seizure in extraordinary cases. State-law claims remain available too." },
    { q: "Why do many NDAs protect trade secrets for longer than the general confidentiality term?", a: ["A fixed end date can destroy trade secret status", "Trade secrets expire after 20 years", "A statute requires it"], c: 0, x: "Letting confidentiality lapse after, say, three years can end secrecy, so trade secrets often stay protected as long as they qualify." },
    { q: "NDA 'return or destroy' clauses commonly carve out copies kept…", a: ["In automatic backups or for legal compliance", "On personal phones", "In the discloser's own office"], c: 0, x: "Wiping every backup is impractical, so retained copies typically remain subject to the confidentiality obligations." },
    { q: "In M&A confidentiality agreements, a 'standstill' provision stops the recipient from…", a: ["Buying the target's shares or launching a hostile bid", "Hiring any staff anywhere", "Talking to its own lawyers"], c: 0, x: "Delaware courts have scrutinised 'don't ask, don't waive' standstills that bar even private requests for a waiver." },
    { q: "Martin Marietta v. Vulcan Materials (Del. 2012) enjoined a hostile bid because the bidder had…", a: ["Misused information covered by confidentiality agreements", "Bribed directors", "Missed a filing deadline"], c: 0, x: "Delaware enforced the NDAs' use and disclosure limits, halting Martin Marietta's exchange offer for four months." },
    { q: "NDAs often state that a breach would cause 'irreparable harm'. The aim is to support…", a: ["Injunctive relief", "Punitive damages", "Criminal prosecution"], c: 0, x: "Courts aren't bound by the recital, but it helps: money is a poor remedy once secrets are out." },
    { q: "The Bayh-Dole Act of 1980 lets US universities and small businesses…", a: ["Elect to own inventions from federally funded research", "Avoid all patent fees", "Publish without review"], c: 0, x: "It transformed university technology transfer. The government keeps a non-exclusive licence and 'march-in' rights." },
    { q: "In research contracting, an 'MTA' is a…", a: ["Material Transfer Agreement", "Master Trial Agreement", "Mutual Termination Addendum"], c: 0, x: "MTAs govern sharing of biological samples, compounds or data, covering permitted use, publication and IP ownership." },
    { q: "The UBMTA, a standard template for sharing research materials between institutions, is the…", a: ["Uniform Biological Material Transfer Agreement", "Universal Basic Materials Trade Act", "University Bio-Medical Treaty Agreement"], c: 0, x: "Published by the NIH in the 1990s, it lets signatory institutions transfer materials with a short implementing letter." },
    { q: "Sponsored research agreements commonly let the sponsor delay a university's publication in order to…", a: ["File patent applications", "Rewrite the results", "Block publication permanently"], c: 0, x: "Universities protect academic freedom: review periods are limited, often 30 to 90 days, with no right to suppress results." },
    { q: "In UK practice, a 'sole' licence differs from an 'exclusive' licence because, under a sole licence…", a: ["The licensor may still use the IP itself", "Only one product may be made", "The licensee can't sublicense"], c: 0, x: "An exclusive licence excludes everyone, including the licensor. A sole licence excludes other licensees but not the licensor." },
    { q: "Brulotte v. Thys Co. (1964) held that a patent licence requiring royalties for use after the patent expires is…", a: ["Unenforceable per se", "Valid if agreed", "Automatically doubled"], c: 0, x: "The Supreme Court reaffirmed the rule in Kimble v. Marvel (2015), a case about a Spider-Man web-shooting toy." },
    { q: "Lear, Inc. v. Adkins (1969) held that a patent licensee…", a: ["May challenge the patent's validity", "Must pay royalties forever", "Owns all improvements"], c: 0, x: "The Supreme Court abolished licensee estoppel, prompting licensors to add termination-on-challenge clauses." },
    { q: "MedImmune v. Genentech (2007) held a patent licensee can challenge validity…", a: ["Without first stopping royalty payments", "Only after the licence expires", "Only in arbitration"], c: 0, x: "The Supreme Court found a real controversy even while the licensee kept paying royalties under protest." },
    { q: "A 'most favoured licensee' clause promises the licensee…", a: ["Terms at least as good as later licensees get", "First choice of new products", "A discount for prompt payment"], c: 0, x: "Drafting comparability is the hard part: later licences often differ in scope, field, territory or term." },
    { q: "A 'field of use' restriction in a licence limits…", a: ["The applications or markets where the IP may be used", "The physical site where products are made", "The licensor's own research"], c: 0, x: "One patent can be licensed to different companies for, say, human therapeutics and veterinary use." },
    { q: "Section 365(n) of the US Bankruptcy Code protects…", a: ["IP licensees when a licensor goes bankrupt", "Landlords from tenant default", "Creditors from preferences"], c: 0, x: "Licensees may elect to keep their licensed rights even if the bankrupt licensor rejects the contract." },
    { q: "In Mission Product Holdings v. Tempnology (2019), the Supreme Court held that rejecting a trademark licence in bankruptcy…", a: ["Operates as a breach, not a rescission", "Terminates all the licensee's rights", "Is prohibited"], c: 0, x: "Because rejection is a breach, the licensee's rights don't simply vanish, just as they wouldn't outside bankruptcy." },
    { q: "A software 'source code escrow' arrangement protects the licensee if…", a: ["The vendor fails or stops supporting the product", "The code is pirated", "Exchange rates shift"], c: 0, x: "A neutral agent holds the code and releases it on defined trigger events. Regular verification makes escrow meaningful." },
    { q: "The GNU General Public License is called 'copyleft' because it requires that…", a: ["Distributed derivative works use the same licence", "No copyright notice appear", "Royalties go to the FSF"], c: 0, x: "Permissive licences such as MIT and BSD impose no such requirement, a key point in open-source due diligence." },
    { q: "In services contracting, a 'SOW' is a…", a: ["Statement of Work", "Schedule of Warranties", "Summary of Waivers"], c: 0, x: "A master services agreement sets legal terms once; individual SOWs define deliverables, timelines and fees." },
    { q: "An 'order of precedence' clause in a master services agreement tells you…", a: ["Which document wins if they conflict", "Who signs first", "Which invoices are paid first"], c: 0, x: "Many MSAs rank themselves above SOWs unless a SOW expressly says it overrides a specific MSA provision." },
    { q: "Under the US Copyright Act, software commissioned from an independent contractor is generally NOT a 'work made for hire' because…", a: ["Software isn't among the nine statutory categories", "Software isn't copyrightable", "Only federal contracts qualify"], c: 0, x: "That's why services agreements back up 'work for hire' language with an express assignment of copyright." },
    { q: "In a service level agreement, 'service credits' are usually…", a: ["Fee reductions for missed service levels", "Bonuses for overperformance", "Loyalty points for users"], c: 0, x: "Suppliers often make credits the sole remedy for SLA failures; customers push for termination rights on chronic failure." },
    { q: "A 99.9% monthly availability commitment allows roughly how much downtime in a 30-day month?", a: ["About 43 minutes", "About 4 hours", "About 4 minutes"], c: 0, x: "Each extra 'nine' cuts allowed downtime tenfold: 99.99% allows only about 4.3 minutes a month." },
    { q: "A 'termination for convenience' clause lets a party end the contract…", a: ["Without cause, usually on notice", "Only after a material breach", "Only by mutual agreement"], c: 0, x: "Common in US government and services contracts. Suppliers often negotiate wind-down or early-termination fees in exchange." },
    { q: "A 'cure period' in a termination clause gives the breaching party…", a: ["Time to fix the breach before termination", "A right to medical leave", "A price reduction"], c: 0, x: "Thirty days is common. Some breaches, such as a confidentiality leak, may be treated as incapable of cure." },
    { q: "A common SaaS liability cap is set by reference to…", a: ["Fees paid in the preceding 12 months", "The supplier's market value", "The premium for its insurance"], c: 0, x: "Higher 'super-caps' or uncapped carve-outs are then negotiated for data breaches, confidentiality and indemnities." },
    { q: "BATNA, a core negotiation concept, stands for…", a: ["Best Alternative to a Negotiated Agreement", "Basic Agreement Terms and Negotiation Aims", "Binding Arbitration Then Negotiated Award"], c: 0, x: "Coined in 'Getting to Yes' (1981) by Roger Fisher and William Ury of the Harvard Negotiation Project." },
    { q: "In negotiation, 'ZOPA' refers to…", a: ["The zone of possible agreement", "A zero-option pricing approach", "The zone of protected assets"], c: 0, x: "It's the overlap between the parties' walk-away points. With no overlap, there is no deal to be had." },
    { q: "Making the first offer to set a reference point for the rest of the negotiation is known as…", a: ["Anchoring", "Logrolling", "Nibbling"], c: 0, x: "Research shows first numbers pull outcomes toward them, which is why an ambitious but credible opening often pays." },
    { q: "'Logrolling' in negotiation means…", a: ["Trading issues you value less for ones you value more", "Delaying until the deadline", "Repeating the same offer"], c: 0, x: "It creates value: concede on payment terms you barely care about to win the liability cap you need." },
    { q: "A 'nibble' is a negotiating tactic in which a party…", a: ["Asks for a small extra concession after agreement", "Takes a long lunch to stall", "Opens with a low offer"], c: 0, x: "Counter it by asking for something in return, or by making clear the deal was agreed as a package." },
    { q: "'Getting to Yes' urges negotiators to focus on…", a: ["Interests, not positions", "Positions, not interests", "Deadlines, not terms"], c: 0, x: "Behind every position ('a five-year term') lies an interest ('budget certainty') that might be met in other ways." },
    { q: "In contract negotiation, a 'redline' is…", a: ["A marked-up draft showing changes", "A final signature page", "An invoice for legal fees"], c: 0, x: "Named for red ink on paper drafts; today it's tracked changes or a comparison document between versions." },
    { q: "Term sheets and letters of intent are usually expressly non-binding, except for clauses such as…", a: ["Confidentiality and exclusivity", "Price and quantity", "Warranties and indemnities"], c: 0, x: "If the language is unclear, courts may still find a binding preliminary agreement or a duty to negotiate in good faith." },
    { q: "Walford v Miles (1992) held that, under English law, a bare agreement to negotiate in good faith is…", a: ["Unenforceable for uncertainty", "Implied in every contract", "Binding for one year"], c: 0, x: "A 'lock-out' agreement not to negotiate with others for a fixed period, by contrast, can be enforceable." },
    { q: "Yam Seng v International Trade Corp (2013) is notable for implying a duty of good faith into…", a: ["A long-term distribution agreement", "Every English contract", "Consumer loans"], c: 0, x: "Leggatt J suggested 'relational' contracts may carry implied duties of honesty and fair dealing, a notable shift for English law." },
    { q: "Bhasin v. Hrynew (2014) recognised a general duty of honest contractual performance in…", a: ["Canada", "Australia", "England"], c: 0, x: "The Supreme Court of Canada held parties must not lie or knowingly mislead each other about matters directly linked to performance." },
    { q: "Which ancient code included rules on deposits, loans, hire and building contracts around 1750 BC?", a: ["The Code of Hammurabi", "The Twelve Tables", "Justinian's Digest"], c: 0, x: "The Babylonian code made builders answerable for collapses, an early form of construction liability." },
    { q: "The Roman 'stipulatio' was a contract formed by…", a: ["A formal spoken question and answer", "Sealing with wax", "Handing over a coin"], c: 0, x: "'Spondesne?' 'Spondeo.' ('Do you promise?' 'I promise.') The form, not consideration, made it binding." },
    { q: "'Pacta sunt servanda' means…", a: ["Agreements must be kept", "Peace serves all", "Contracts serve the state"], c: 0, x: "The foundational maxim of contract and treaty law, codified in Article 26 of the 1969 Vienna Convention on the Law of Treaties." },
    { q: "'Rebus sic stantibus' is the principle that an obligation may lapse when…", a: ["Circumstances fundamentally change", "A party dies", "The document is lost"], c: 0, x: "Recognised for treaties in Article 62 of the Vienna Convention on the Law of Treaties, it is a civil-law cousin of frustration." },
    { q: "'Caveat emptor' translates as…", a: ["Let the buyer beware", "Let the seller decide", "Beware of the empire"], c: 0, x: "Implied warranties and disclosure duties have eroded it, but it still shapes many 'as is' sales." },
    { q: "The phrase 'consensus ad idem' refers to…", a: ["A meeting of minds on the same thing", "Unanimous board approval", "Agreement on price alone"], c: 0, x: "Modern law tests it objectively: what reasonable people would take the parties to have agreed." },
    { q: "'Quantum meruit' literally means…", a: ["As much as he has deserved", "The amount in the contract", "Whatever the market bears"], c: 0, x: "It allows recovery of the reasonable value of services where there's no enforceable price, such as work under a failed contract." },
    { q: "The counterpart of quantum meruit for goods supplied is…", a: ["Quantum valebant", "Res ipsa loquitur", "Pro tanto"], c: 0, x: "'As much as they were worth': a claim for the reasonable value of goods delivered without an enforceable price." },
    { q: "Before modern contract law, English courts enforced informal promises through the action of…", a: ["Assumpsit", "Replevin", "Habeas corpus"], c: 0, x: "Latin for 'he undertook'. Slade's Case (1602) confirmed assumpsit could be used to recover debts." },
    { q: "Historically, a promise 'under seal' was enforceable without…", a: ["Consideration", "Delivery", "Being in writing"], c: 0, x: "Many US states have abolished or limited the seal's effect. In England, a deed still binds without consideration." },
    { q: "Under England's Limitation Act 1980, a claim on a contract executed as a deed must generally be brought within…", a: ["12 years", "6 years", "3 years"], c: 0, x: "Simple contracts get six years. The longer period is one reason parties execute key documents as deeds." },
    { q: "Which 18th-century judge is often called the founder of English commercial law?", a: ["Lord Mansfield", "Lord Coke", "Lord Eldon"], c: 0, x: "As Chief Justice of the King's Bench from 1756 to 1788, he absorbed merchant custom into the common law." },
    { q: "'Lex mercatoria' refers to…", a: ["The law merchant: customs of traders", "Roman tax law", "Maritime salvage rules only"], c: 0, x: "Medieval merchants' courts applied fast, practical trade customs, later absorbed into the common law." },
    { q: "The UNIDROIT Principles of International Commercial Contracts were first published in…", a: ["1994", "1964", "2020"], c: 0, x: "These non-binding 'soft law' rules can be chosen by parties or applied by arbitrators. Later editions followed in 2004, 2010 and 2016." },
    { q: "Medieval English 'piepowder' courts handled disputes at…", a: ["Fairs and markets", "Royal palaces", "Monasteries"], c: 0, x: "The name comes from 'pieds poudrés', the dusty feet of travelling merchants who needed justice on the spot." },
    { q: "The first law school casebook, published by Christopher Columbus Langdell in 1871, covered…", a: ["Contracts", "Torts", "Constitutional law"], c: 0, x: "'A Selection of Cases on the Law of Contracts' launched the Harvard case method that still dominates US legal education." },
    { q: "Which scholar wrote the multi-volume treatise 'The Law of Contracts' (1920) and was Reporter for the first Restatement of Contracts?", a: ["Samuel Williston", "Arthur Corbin", "Karl Llewellyn"], c: 0, x: "His great rival Arthur Corbin of Yale championed a more flexible, context-driven approach." },
    { q: "Grant Gilmore's provocative 1974 book on contract theory was titled…", a: ["The Death of Contract", "The Myth of Consent", "Contract Unbound"], c: 0, x: "Gilmore argued contract was being reabsorbed into tort through reliance and promissory estoppel." },
    { q: "Oliver Wendell Holmes Jr. said the duty to keep a contract at common law means a prediction that you must…", a: ["Pay damages if you do not keep it", "Go to jail if you break it", "Apologise publicly"], c: 0, x: "From 'The Path of the Law' (1897), an intellectual ancestor of law-and-economics thinking about breach." },
    { q: "Sir Henry Maine wrote that progressive societies have moved 'from Status to…'", a: ["Contract", "Property", "Freedom"], c: 0, x: "From 'Ancient Law' (1861): legal relations shifted from fixed family status toward freely chosen agreements." },
    { q: "Lochner v. New York (1905) struck down a limit on bakers' working hours in the name of…", a: ["Freedom of contract", "States' rights", "Free speech"], c: 0, x: "The 'Lochner era' ended with West Coast Hotel v. Parrish (1937), which upheld a minimum wage law." },
    { q: "The US Constitution's Contracts Clause forbids states from passing laws…", a: ["Impairing the obligation of contracts", "Taxing contracts", "Requiring written contracts"], c: 0, x: "Article I, Section 10. Dartmouth College v. Woodward (1819) applied it to protect a corporate charter." },
    { q: "Home Building & Loan v. Blaisdell (1934) upheld, against a Contracts Clause challenge, a Depression-era…", a: ["Mortgage foreclosure moratorium", "Minimum wage law", "Ban on child labour"], c: 0, x: "The Supreme Court allowed Minnesota's temporary relief as a reasonable exercise of state power in an emergency." },
    { q: "The 1935 'Gold Clause Cases' concerned contract terms promising payment in…", a: ["Gold or its equivalent", "Foreign currency", "Grain"], c: 0, x: "Congress had voided gold clauses in 1933. The Supreme Court largely let that stand for private contracts." },
    { q: "The sale of Babe Ruth's contract from the Boston Red Sox to the New York Yankees, announced in January 1920, was for…", a: ["$100,000", "$1 million", "$10,000"], c: 0, x: "The deal spawned the legend of the 'Curse of the Bambino', which Red Sox fans say lasted until 2004." },
    { q: "Arthur Guinness's 1759 lease of the St James's Gate brewery in Dublin ran for…", a: ["9,000 years", "999 years", "99 years"], c: 0, x: "The agreed rent was £45 a year, making it one of the most famous leases in business history." },
    { q: "Olivia de Havilland's 1944 court victory over Warner Bros. established that California personal service contracts…", a: ["Can't be enforced beyond seven calendar years", "Must be renewed annually", "Can't include any options"], c: 0, x: "Studios had extended contracts by adding suspension time. California Labor Code § 2855 is still called the 'De Havilland Law'." },
    { q: "Flood v. Kuhn (1972) left in place baseball's 'reserve clause', which bound players to…", a: ["Their club, season after season", "One city's stadium", "A league-wide fixed salary"], c: 0, x: "The Supreme Court kept baseball's antitrust exemption. A 1975 arbitration ruling later opened the door to free agency." },
    { q: "The 1995 Bosman ruling of the European Court of Justice allowed footballers to…", a: ["Move freely when their contracts expired", "Negotiate image rights", "Choose any national team"], c: 0, x: "Transfer fees for out-of-contract players moving between EU member states were held to breach free movement of workers." },
    { q: "In Buchwald v. Paramount (1990), a California court criticised 'net profit' terms in a dispute over which film?", a: ["Coming to America", "The Godfather", "Top Gun"], c: 0, x: "Columnist Art Buchwald's treatment was found to be the film's basis, and the case became a byword for 'Hollywood accounting'." },
    { q: "In a traditional contract, the 'Whereas' clauses are known as…", a: ["Recitals", "Covenants", "Representations"], c: 0, x: "Recitals give background and purpose. They usually aren't operative, but courts may use them to resolve ambiguity." },
    { q: "The archaic word 'WITNESSETH' in old contracts means…", a: ["Shows or bears witness", "Signed before a witness", "Notarised"], c: 0, x: "It's a verb ('This Agreement witnesseth that…'), often misread as a heading. Modern drafters drop it." },
    { q: "Why were old deeds called 'indentures'?", a: ["Copies were cut apart along a wavy line", "They were dented by a seal", "They bound apprentices only"], c: 0, x: "Duplicates written on one sheet were separated by an indented cut; matching the edges proved authenticity." },
    { q: "The term 'boilerplate' for standard contract language comes from…", a: ["Ready-made printing plates for syndicated text", "Steam-boiler insurance contracts", "Shipbuilding specifications"], c: 0, x: "Newspapers once received pre-cast plates of stock text that nobody changed, resembling the steel plates used to make boilers." },
    { q: "In the phrase 'signed, sealed and delivered', the 'delivered' refers to…", a: ["The intention to be bound by the deed", "Physical mailing", "Courier receipt"], c: 0, x: "Delivery of a deed is about intent to be bound, not handing it over. A deed can even be delivered in escrow." },
    { q: "The letters 'L.S.' beside a signature line stand for…", a: ["Locus sigilli: place of the seal", "Legal signatory", "Lawful signature"], c: 0, x: "In some US states, writing 'L.S.' or 'Seal' can still give a document sealed status." },
    { q: "Delaware's statute (6 Del. C. § 2708) guarantees respect for a choice of Delaware law in contracts involving at least…", a: ["$100,000", "$1 million", "$10,000"], c: 0, x: "New York has a similar rule, General Obligations Law § 5-1401, for transactions of $250,000 or more." },
    { q: "New York General Obligations Law § 5-1402 lets parties choose New York courts, even without other ties, if the deal is at least…", a: ["$1 million", "$250,000", "$10 million"], c: 0, x: "Together with § 5-1401 on choice of law, it helps make New York a hub for commercial contracts." },
    { q: "In the EU, which regulation determines the law applicable to contractual obligations?", a: ["Rome I", "Brussels I", "Rome II"], c: 0, x: "Rome II covers non-contractual obligations; Brussels I (recast) deals with jurisdiction and judgments." },
    { q: "The Hague Convention on Choice of Court Agreements (2005) mainly gives effect to…", a: ["Exclusive jurisdiction clauses", "Arbitration agreements", "Non-exclusive clauses only"], c: 0, x: "The UK joined in its own right after Brexit. The separate 2019 Hague Judgments Convention covers judgments more broadly." },
    { q: "Rectification lets a court…", a: ["Correct a document to match what was actually agreed", "Rewrite a bad bargain", "Add missing parties"], c: 0, x: "It needs convincing proof that the writing fails to record the parties' real agreement, or that one side knew of the other's mistake." },
    { q: "'Non est factum' ('it is not my deed') can void a signed document only if…", a: ["The signer was fundamentally mistaken about it without carelessness", "The signer dislikes the terms", "It was signed on a weekend"], c: 0, x: "Saunders v Anglia Building Society (1970) confirmed the plea is narrow. Carelessness defeats it." },
    { q: "Ashbury Railway Carriage v Riche (1875) held a company's contract void because it was…", a: ["Ultra vires the company's objects", "Signed on a Sunday", "Not under seal"], c: 0, x: "Modern company law, such as s.39 of the UK Companies Act 2006, has largely removed this risk for outsiders." },
    { q: "Freeman & Lockyer v Buckhurst Park Properties (1964) bound a company to a contract made by a director acting as managing director with…", a: ["Apparent (ostensible) authority", "Written board approval", "A forged seal"], c: 0, x: "The board let him act as MD, so outsiders could rely on his apparent authority. It's why signing authority matters." },
    { q: "The 'indoor management rule' from Royal British Bank v Turquand (1856) lets outsiders assume a company has…", a: ["Complied with its internal procedures", "Unlimited liability", "Audited accounts"], c: 0, x: "A third party needn't check that internal resolutions were passed, unless something puts it on inquiry." },
    { q: "A guarantee differs from an indemnity because a guarantor's liability is…", a: ["Secondary to the principal debtor's", "Always unlimited", "Payable only in gold"], c: 0, x: "If the underlying obligation is void, a guarantee usually falls with it, while a primary indemnity may survive." },
    { q: "In Kleinwort Benson v Malaysia Mining (1989), a parent's 'comfort letter' saying its policy was to ensure its subsidiary met its liabilities was…", a: ["Not a binding promise", "A binding guarantee", "A fraudulent statement"], c: 0, x: "The Court of Appeal read it as a statement of present policy, not a contractual promise about the future." },
    { q: "Under Barry v Davies (2000), an auctioneer who refuses to sell to the highest bidder at an auction advertised 'without reserve' may be liable to…", a: ["That highest bidder", "The seller", "No one"], c: 0, x: "Holding an auction without reserve is a collateral promise to sell to the highest genuine bidder." },
    { q: "Payne v Cave (1789) established that at an auction, a bid is…", a: ["An offer that can be withdrawn before the hammer falls", "An acceptance", "Irrevocable once made"], c: 0, x: "The auctioneer's call for bids is an invitation to treat; the fall of the hammer is the acceptance." },
    { q: "In Blackpool and Fylde Aero Club v Blackpool BC (1990), the council was liable for ignoring a tender that was…", a: ["Put in its letterbox on time", "Faxed after the deadline", "Submitted by a rival"], c: 0, x: "Inviting tenders from selected parties under strict rules implied a promise to consider every conforming bid." },
    { q: "Brogden v Metropolitan Railway (1877) held that a contract was formed by…", a: ["Conduct: ordering and supplying coal on the draft terms", "A signed document", "An oral agreement at a meeting"], c: 0, x: "The draft agreement was never formally completed, but dealings on its terms showed acceptance." },
    { q: "Liverpool City Council v Irwin implied a term into council tenancies requiring the landlord to…", a: ["Take reasonable care of common parts such as lifts", "Provide free heating", "Repaint flats yearly"], c: 0, x: "Terms implied in law attach to a type of contract as a necessary incident: here lifts, stairs and rubbish chutes." },
    { q: "In Bannerman v White (1861), a seller's assurance that no sulphur had been used on which goods was held to be a contract term?", a: ["Hops", "Wine grapes", "Wool"], c: 0, x: "The buyer said he wouldn't even ask the price if sulphur had been used, showing how important the statement was." },
    { q: "With v O'Flanagan (1936) held a seller liable when a true statement about a medical practice's income…", a: ["Became untrue before the contract and wasn't corrected", "Was exaggerated by the buyer", "Was made by an accountant"], c: 0, x: "A representation is treated as continuing. If circumstances change before contracting, silence can make it a misrepresentation." },
    { q: "Redgrave v Hurd (1881) held a misrepresentation victim can rescind even though they…", a: ["Could have discovered the truth with diligence", "Never relied on it", "Wrote the statement themselves"], c: 0, x: "The buyer of a solicitor's practice needn't have checked the papers he was offered. It's no defence that he could have." },
    { q: "In Leaf v International Galleries (1950), a buyer who discovered five years later that his 'Constable' wasn't genuine…", a: ["Was too late to rescind", "Got full rescission", "Recovered double damages"], c: 0, x: "Court of Appeal: rescission for innocent misrepresentation must be sought within a reasonable time." },
    { q: "A 'condition precedent' is an event that must occur…", a: ["Before a duty to perform arises", "After the contract ends", "Only if both parties later agree"], c: 0, x: "Courts prefer to read ambiguous language as a promise rather than a condition, to avoid harsh forfeitures." },
    { q: "In construction subcontracts, a 'pay-if-paid' clause differs from 'pay-when-paid' because it…", a: ["Shifts the risk of owner non-payment to the subcontractor", "Sets payment timing only", "Requires payment in advance"], c: 0, x: "Many courts read pay-when-paid as timing only. Some states, such as New York, refuse to enforce pay-if-paid clauses." },
    { q: "Cashing a 'payment in full' cheque on a genuinely disputed debt can create…", a: ["An accord and satisfaction", "A novation", "An option contract"], c: 0, x: "In the US, UCC § 3-311 governs instruments tendered in good faith with a conspicuous full-satisfaction statement." },
    { q: "A 'novation' differs from an assignment because it…", a: ["Substitutes a new party and releases the old one", "Transfers only benefits", "Needs no one's consent"], c: 0, x: "All parties must agree. With a plain assignment and delegation, the original party usually stays liable." },
    { q: "In Atlas Express v Kafco, a carrier's demand for a higher price was unenforceable because the small firm depended on deliveries to…", a: ["Woolworths", "The Royal Mail", "Harrods"], c: 0, x: "Facing a refusal to deliver its basketware, Kafco had no practical choice: a classic economic duress case." },
    { q: "RBS v Etridge (No 2) (2001) set out steps a bank must take when a wife guarantees her husband's debts, centred on…", a: ["Independent legal advice", "A notarised video", "A 14-day cooling-off period"], c: 0, x: "The House of Lords required the bank to ensure a solicitor explained the risks, guarding against undue influence claims." },
    { q: "In Lloyds Bank v Bundy, Lord Denning proposed a general principle of…", a: ["Inequality of bargaining power", "Promissory estoppel", "Efficient breach"], c: 0, x: "An elderly farmer's guarantee was set aside. The other judges relied on undue influence, and Denning's general principle never took hold." },
    { q: "Patel v Mirza (2016) replaced a rigid reliance test for illegality in English law with…", a: ["A policy-based 'range of factors' approach", "An absolute bar on recovery", "A jury question"], c: 0, x: "Money paid for a planned insider-dealing bet that never happened could be recovered. The court weighed the policies at stake." },
    { q: "The maxim 'ex turpi causa non oritur actio' means…", a: ["No action arises from a disgraceful cause", "Turpitude must be pleaded", "The cause follows the action"], c: 0, x: "The illegality defence, classically stated by Lord Mansfield in Holman v Johnson (1775)." },
    { q: "Courts most readily enforce online terms presented as 'clickwrap', which requires users to…", a: ["Click 'I agree' or similar", "Merely visit the website", "Print the terms"], c: 0, x: "Browsewrap, with terms behind a footer link, often fails for lack of notice and assent, as in Nguyen v. Barnes & Noble (2014)." },
    { q: "The Law Commission of England and Wales concluded in 2019 that an electronic signature…", a: ["Can validly execute documents, including deeds", "Is never valid for contracts", "Requires a qualified certificate"], c: 0, x: "E-signatures can satisfy signing requirements where there is intent to authenticate, though a deed's witness must still be present." },
    { q: "After R (Mercury Tax Group) v HMRC (2008), English lawyers adopted 'virtual signing' protocols because the court criticised…", a: ["Attaching signature pages to a different final draft", "Signing in blue ink", "Faxing contracts abroad"], c: 0, x: "A Law Society practice note sets out safe options for signing by emailed PDF signature pages." },
    { q: "Carter v Boehm (1766) is Lord Mansfield's foundational case on the insurance duty of…", a: ["Utmost good faith and disclosure", "Strict liability", "Subrogation"], c: 0, x: "Uberrimae fidei: the insured must disclose material facts. In the UK, the Insurance Act 2015 reshaped the duty for business insurance." },
    { q: "The 'Christian doctrine' in US government contracting reads mandatory regulatory clauses into contracts…", a: ["Even when they were left out", "Only for religious organisations", "Only when separately signed"], c: 0, x: "From G.L. Christian & Associates v. United States (1963): required clauses apply by operation of law." },
    { q: "US federal procurement contracts are governed mainly by the…", a: ["Federal Acquisition Regulation (FAR)", "Uniform Commercial Code", "Restatement of Contracts"], c: 0, x: "The FAR, Title 48 of the Code of Federal Regulations, supplies standard clauses that contracting officers must include." },
    { q: "New York's statute of limitations for breach of contract is generally…", a: ["Six years", "Four years", "Ten years"], c: 0, x: "CPLR 213 sets six years, generally running from the breach itself rather than from when it was discovered." },
    { q: "Delaware's general limitations period for breach of contract is…", a: ["Three years", "Six years", "Ten years"], c: 0, x: "10 Del. C. § 8106 sets three years, but parties may agree to up to 20 years for contracts involving at least $100,000." },
    { q: "UCC Article 2A governs…", a: ["Leases of goods", "Leases of real estate", "Letters of credit"], c: 0, x: "Added in 1987, it largely mirrors Article 2's sales rules, adapted for leasing. Article 5 covers letters of credit." },
    { q: "Most commercial letters of credit incorporate the ICC's rules known as…", a: ["UCP 600", "Incoterms 2020", "URDG 758"], c: 0, x: "The Uniform Customs and Practice for Documentary Credits, 2007 revision. Banks deal in documents, not goods." },
    { q: "Under UCC § 2-609, a party with reasonable grounds for insecurity may…", a: ["Demand adequate assurance of performance", "Terminate immediately", "Double the price"], c: 0, x: "Failure to give assurance within a reasonable time, not exceeding 30 days, is a repudiation." },
    { q: "UCC § 2-615 excuses a seller's delay or non-delivery when performance becomes…", a: ["Commercially impracticable through an unforeseen contingency", "Less profitable", "Inconvenient"], c: 0, x: "Mere cost increases rarely qualify. A seller with partial supply must allocate it fairly among customers." },
    { q: "In Aluminum Co. of America v. Essex Group (1980), a federal court took the unusual step of…", a: ["Reforming a long-term price formula", "Voiding every Alcoa contract", "Ordering arbitration"], c: 0, x: "A price index failed to track Alcoa's soaring energy costs, so the court adjusted the price. The decision is rarely followed." },
    { q: "When two negotiators on the same side play contrasting tough and friendly roles, the tactic is called…", a: ["Good cop, bad cop", "Boulwarism", "Salami slicing"], c: 0, x: "The friendly one seems like an ally. Counter it by naming the tactic or treating both as one team." },
    { q: "'Boulwarism', named after a General Electric executive, describes…", a: ["A take-it-or-leave-it first offer", "Splitting the difference", "Endless counteroffers"], c: 0, x: "Lemuel Boulware's labour strategy was later found by the NLRB to breach the duty to bargain in good faith." },
    { q: "'Salami tactics' in negotiation means…", a: ["Winning concessions slice by slice", "Bringing lunch to soften the mood", "Cutting a deal into two contracts"], c: 0, x: "Each ask looks too small to fight; together they add up to a big concession." },
    { q: "A negotiator's 'reservation point' or walk-away point is…", a: ["The least favourable deal they would still accept", "Their opening offer", "The deadline for agreement"], c: 0, x: "It should be set by your BATNA, not by the other side's first number." },
    { q: "Why do many lawyers want to 'hold the pen' on the first draft?", a: ["The first draft frames the deal and its defaults", "Drafters pay lower fees", "The drafter can't be sued"], c: 0, x: "Every departure must then be proposed by the other side, which costs time and goodwill: anchoring for terms." },
    { q: "In M&A, the gap between 'signing' and 'closing' exists mainly to allow…", a: ["Regulatory approvals and other conditions to be satisfied", "Lawyers to proofread", "The price to be renegotiated"], c: 0, x: "Interim covenants govern conduct in between, and MAC clauses address bad news that arrives before closing." },
    { q: "A 'pro-sandbagging' clause lets a buyer…", a: ["Claim for a breach of warranty it knew about at signing", "Delay payment indefinitely", "Hide its own financials"], c: 0, x: "Anti-sandbagging clauses do the opposite. Where the contract is silent, the answer varies by jurisdiction." },
    { q: "An 'earn-out' in an acquisition makes part of the price depend on…", a: ["The business's post-closing performance", "The buyer's share price", "Interest rates"], c: 0, x: "Earn-outs bridge valuation gaps but breed disputes over how the buyer runs the business afterward." },
    { q: "In an acquisition agreement, an indemnity 'basket' is…", a: ["A threshold of losses before claims can be made", "A list of excluded assets", "A pool of escrowed shares"], c: 0, x: "A 'deductible' basket pays only the excess; a 'tipping' basket pays from the first dollar once the threshold is hit." },
    { q: "French contract law traditionally required 'cause' rather than consideration, a requirement removed by reforms in…", a: ["2016", "1804", "1958"], c: 0, x: "The 2016 reform of the Code civil replaced 'cause' with a requirement of lawful and certain content." },
    { q: "The French Civil Code, foundational for civil-law contract rules, was enacted in…", a: ["1804", "1789", "1871"], c: 0, x: "The Napoleonic Code influenced contract law across Europe, Latin America and Louisiana." },
    { q: "Germany's Civil Code (BGB), known for § 242 on good faith ('Treu und Glauben'), took effect in…", a: ["1900", "1871", "1949"], c: 0, x: "§ 242 grew into a powerful tool for adjusting contracts, including changed circumstances, now codified in § 313." },
    { q: "'Culpa in contrahendo', the civil-law doctrine of fault in contract negotiations, was famously articulated by…", a: ["Rudolf von Jhering", "Friedrich Carl von Savigny", "Hugo Grotius"], c: 0, x: "His 1861 essay argued that a party whose careless pre-contract conduct causes loss should compensate the other." },
    { q: "Unlike English law, Scots law…", a: ["Doesn't require consideration", "Has no contract law", "Requires every contract to be notarised"], c: 0, x: "A gratuitous unilateral promise can bind in Scotland, though some must be in writing under the Requirements of Writing (Scotland) Act 1995." },
    { q: "A 'further assurances' clause obliges the parties to…", a: ["Sign documents and take steps needed to give effect to the deal", "Buy extra insurance", "Repeat warranties annually"], c: 0, x: "Useful where transfers of IP or other assets need separate formal documents after signing." },
    { q: "Why do contracts often say 'headings are for convenience only'?", a: ["So headings don't change a clause's meaning", "To save printing costs", "Because headings are unlawful"], c: 0, x: "A misleading heading could otherwise be used to narrow or expand the clause beneath it." },
    { q: "A relationship-of-the-parties clause aims to prevent the contract being treated as creating…", a: ["A partnership, agency or employment", "A late-payment penalty", "A price escalator"], c: 0, x: "Courts look at substance over labels, especially for worker classification, but the clause helps." },
    { q: "A 'no set-off' clause requires a party to…", a: ["Pay in full despite its own counterclaims", "Avoid offsetting carbon emissions", "Send separate invoices"], c: 0, x: "It keeps cash flowing: disputes are resolved separately rather than by withholding payment." },
    { q: "A tiered or 'escalation' dispute resolution clause typically requires…", a: ["Executive talks or mediation before litigation", "Higher fees each year", "A jury trial"], c: 0, x: "Courts enforce the steps if they're sufficiently certain. Vague 'friendly discussions' clauses may not bind." },
    { q: "Licensors include 'audit rights' clauses mainly to…", a: ["Verify royalty reports", "Inspect the licensee's tax returns", "Approve the licensee's hiring"], c: 0, x: "Typical terms: reasonable notice, an independent auditor, and the licensee paying audit costs if underpayment exceeds a threshold." },
    { q: "A tax 'gross-up' clause ensures the payee…", a: ["Receives the full amount after any withholding tax", "Pays all taxes for both sides", "Gets fees that rise annually"], c: 0, x: "If tax must be withheld, the payer increases the payment so the net amount equals what would otherwise have been paid." },
    { q: "Anti-corruption clauses in commercial contracts commonly reference the US FCPA and the UK…", a: ["Bribery Act 2010", "Companies Act 1985", "Fraud Act 1990"], c: 0, x: "The UK Act's corporate offence of failing to prevent bribery makes contractual compliance commitments valuable." },
    { q: "Under the GDPR, the contract between a controller and a processor is governed by…", a: ["Article 28", "Article 1", "Article 99"], c: 0, x: "It must cover subject matter, duration, security, sub-processors, audits and deletion or return of data." },
    { q: "The European Commission's current Standard Contractual Clauses for international data transfers were adopted in…", a: ["2021", "1995", "2010"], c: 0, x: "They replaced older sets after the Schrems II judgment (2020), which also invalidated the EU-US Privacy Shield." },
    { q: "Impression Products v. Lexmark (2017) held that selling a patented printer cartridge…", a: ["Exhausts patent rights despite post-sale restrictions", "Lets the patentee control resale forever", "Voids the patent"], c: 0, x: "Restrictions may still be enforceable as contract terms, but not through patent infringement claims, even for sales abroad." },
    { q: "A trademark licensor who fails to control the quality of the licensee's goods risks…", a: ["Abandonment through 'naked licensing'", "Automatically doubled royalties", "Gaining a patent"], c: 0, x: "Quality control clauses are essential: without them, the mark may stop signifying a single source." },
    { q: "Under US copyright law, an assignment or exclusive licence of copyright must be…", a: ["In a signed writing", "Registered within 30 days", "Notarised"], c: 0, x: "17 U.S.C. § 204(a). Non-exclusive licences, by contrast, can be oral or implied from conduct." },
    { q: "Under § 203 of the US Copyright Act, authors can terminate grants made from 1978 onward after…", a: ["35 years", "10 years", "75 years"], c: 0, x: "The right applies 'notwithstanding any agreement to the contrary', so contracts can't waive it. Works made for hire are excluded." },
